def same_case(c):
    """True for a character that re.I and str.lower() treat alike, so "the regex matches" implies "the lower-cased word is in the
    lower-cased text": ASCII, Latin letters with accents, Cyrillic, and characters with no case (digits, CJK). Left out on purpose:
    ı, İ, ſ, the Kelvin sign, Greek and other letters that re.I pairs with a letter lower() does not turn them into."""
    o = ord(c)
    return o < 128 or (0xC0 <= o <= 0x17E and o not in (0x130, 0x131)) or 0x400 <= o <= 0x4FF or c.lower() == c == c.upper()


def rx_needs(pattern, cap=200, flags=re.I):
    """What a text must contain for this regex to match it, as a list of word sets (lower case): a match needs every word of at
    least one set. An empty list when nothing can be said. Testing 531 role rules against every job title was a fifth of a build
    (profile of 17 Nov 2026: 131 s for 31,800 titles); "is this word in the title" is a hundred times cheaper than a regex search,
    and a rule is still run on every title that passes, so the result is the same (role_slugs below)."""
    try:
        from re import _parser as sp, _constants as sc
    except ImportError:
        return []
    ANY = [frozenset()]                                     # no word is needed
    tell = lambda d: min(max(map(len, c_)) for c_ in d)     # how telling a list is: the longest word of its weakest set
    def both(a, b):                                         # a match needs a set of a and a set of b
        if a == ANY: return b
        if b == ANY: return a
        if len(a) * len(b) > cap: return a if tell(a) >= tell(b) else b       # too many combinations: one side alone is still needed
        return list({x | y for x in a for y in b})
    def need(seq):
        cur, run = ANY, []
        def word():
            w_ = "".join(run).lower(); run.clear()
            return [frozenset({w_})] if all(map(same_case, w_)) else ANY
        for op, av in seq:
            if op is sc.LITERAL:
                run.append(chr(av)); continue
            if run: cur = both(cur, word())
            if op is sc.SUBPATTERN: d = need(av[3])
            elif op is sc.BRANCH:
                d = [c_ for a_ in av[1] for c_ in need(a_)]
                if not all(d): d = ANY                      # one branch needs nothing, so the whole choice needs nothing
            elif op in (sc.MAX_REPEAT, sc.MIN_REPEAT, getattr(sc, "POSSESSIVE_REPEAT", None)) and av[0] >= 1: d = need(av[2])
            elif op is getattr(sc, "ATOMIC_GROUP", None): d = need(av)
            else: d = ANY                                   # character classes, optional parts, look-arounds, anchors promise no word
            cur = both(cur, d)
        if run: cur = both(cur, word())
        return cur
    try:
        d = need(sp.parse(pattern, flags))
    except Exception:
        return []
    return [] if not all(d) else sorted(set(d), key=sorted)


ROLE_NEED = {nm: rx_needs(rx) for nm, _, rx in ROLES}
SAME_CASE = {}


def low_of(text):
    """The lower-case copy of a text that the word tests read (role_slugs, rx_skip), or None for a text with a letter that re.I pairs in its own way
    (then nothing is skipped and every regex is run)."""
    if not text.isascii():
        for c in set(text):
            if c not in SAME_CASE: SAME_CASE[c] = same_case(c)
            if not SAME_CASE[c]: return None
    return text.lower()


def rx_skip(rxs):
    """For compiled regexes that all read the same long texts (job descriptions): returns have and tests.
    have(text) is the set of the words these regexes need that the text has (None for a text with a letter re.I pairs in its own
    way: then nothing is skipped); tests[i](that set) is False when regex i cannot match the text, True when it must be run.
    The interview-theme and office-day regexes read every full description (26 searches of about 230 microseconds a posting,
    a minute of a build on a fifth of the record); two thirds of those searches cannot match, and this says so from one pass
    over the text. Checked against the plain searches on 7,055 descriptions: the same answers."""
    needs = [rx_needs(r.pattern, flags=r.flags) for r in rxs]
    words = sorted({w_ for d in needs for c_ in d for w_ in c_})
    def have(text):
        low = low_of(text)
        return None if low is None else {w_ for w_ in words if w_ in low}
    def test(d):
        if not d: return lambda got: True
        return lambda got: got is None or any(c_ <= got for c_ in d)
    return have, [test(d) for d in needs]


def role_slugs(titles):
    """{title: [role slug, ...]}: the roles each title belongs to, exactly what running every rule on it gives
    ([s_ for s_, (nm, rx) in last.items() if role_hit(nm, rx, title)]), but a rule is run only on a title that has the words the
    rule cannot match without."""
    last = {s_: (nm, rx) for nm, s_, rx in ROLES}               # a slug listed twice keeps its last rule
    pos = {s_: i for i, s_ in enumerate(last)}
    need = {s_: ROLE_NEED.get(nm) or [] for s_, (nm, _) in last.items()}
    always = [s_ for s_ in last if not need[s_]]
    key = defaultdict(list)                                      # the longest word of a set -> (rule, the other words of the set)
    for s_, d in need.items():
        for c_ in d:
            w_ = max(c_, key=len); key[w_].append((s_, c_ - {w_}))
    words = {w_ for d in need.values() for c_ in d for w_ in c_}
    one, by2 = [w_ for w_ in words if len(w_) < 2], defaultdict(list)       # words by their first two characters
    for w_ in words:
        if len(w_) >= 2: by2[w_[:2]].append(w_)
    out = {}
    for t in titles:
        if t in out: continue
        tl = low_of(t)
        if tl is None:                                           # a letter re.I pairs in its own way: every rule, the plain way
            out[t] = [s_ for s_, (nm, rx) in last.items() if role_hit(nm, rx, t)]; continue
        hit = {w_ for w_ in one if w_ in tl}
        for g_ in {tl[i:i + 2] for i in range(len(tl) - 1)}:
            for w_ in by2.get(g_, ()):
                if w_ in tl: hit.add(w_)
        can = set(always)
        for w_ in hit:
            for s_, more in key.get(w_, ()):
                if more <= hit: can.add(s_)
        out[t] = [s_ for s_ in sorted(can, key=pos.__getitem__) if role_hit(last[s_][0], last[s_][1], t)]
    return out


KEEP_CAP = {"German", "French", "Spanish", "Japanese", "Portuguese", "Chinese", "Italian", "Dutch", "Korean"} | set(getattr(roles_info, "KEEP_CAP", ()))   # "Java developer", "Arabic speaking" keep their capital


def rlow(nm):
    """A role or category name inside a sentence: lower case unless it starts with an acronym or a proper name."""
    w = nm.split()[0]
    return nm if w in KEEP_CAP or sum(c.isupper() for c in w) >= 2 else nm[0].lower() + nm[1:]


A_SOUND = re.compile(r"(?i)(?:uni(?![nm])|use|usa|usu|ukr|util|eur|one\b|once\b)")      # a vowel letter read as "you" or "w": a university, a user, a European, a one-page
AN_SOUND = re.compile(r"(?i)(?:hour|honest|honor|heir)")                                  # a silent h: an hourly


def art(nm):
    """"a" or "an" before a name, by its sound: "an HR business partner", "a UX researcher", "an iOS developer",
    "a university recruiter", "a HubSpot job". An acronym is read letter by letter; a word in mixed case (HubSpot, NetSuite) is not."""
    w = nm.split()[0]
    if w[:1].isupper() and (len(w) == 1 or not w[1].islower()): return "an" if w[0] in "AEFHILMNORSX" else "a"      # HR, SEO, MLOps, M&A, X-ray
    if A_SOUND.match(w): return "a"
    if AN_SOUND.match(w): return "an"
    return "an" if nm[0].lower() in "aeiou" else "a"


def person(slug, name):
    """The person who does a kind of work, as the word stands inside a sentence: "customer support specialist" for the role
    "Customer support" (roles_info.PERSON), the name itself for a role named after a person ("software engineer"). Use it only
    where a person is meant ("How to become a …", "What does a … do?"); the field keeps the role's name ("Customer support jobs")."""
    return rlow(roles_info.person(slug, name))


def persons(slug, name):
    """The same in the plural: "customer support specialists", "software engineers", "chiefs of staff"."""
    return roles_info.persons(slug, ROLE_PLURAL.get(name, rlow(name) + "s"))


def become_label(slug):
    """The words of a link to a "how to become" page. "One" stands for the person named in the heading above the link, and a
    role named after a field ("Customer support") names nobody."""
    return "How to start" if slug in roles_info.PERSON else "How to become one"
