EVERY_CUT = []                 # (title of an every_list block, links kept, links to lists under the line left out), for the build's report
# One page per query (the owner, 18 Nov 2026: "никаких конфликтов не должно быть"). The site files a job under a field (/jobs/<field>/),
# under a group of kinds of work (/categories/<group>/), under a kind of work (/roles/<role>/) and under a place, and some of these
# lists carry the same words: "Security jobs" twice, "Consulting jobs in London" twice, "Remote security jobs" twice. Every list page
# of these sections is noted here by the words of its title; at the end of the build one page of each group stays the page for
# search (the section standing first in SAME_QUERY_ORDER) and the others name it as canonical and leave the sitemap. Nothing is
# deleted: the other pages stay for visitors and for the links that lead to them.
SAME_QUERY_ORDER = ("categories", "locations", "jobs", "remote", "skills", "roles", "crypto")
SAME_QUERY = defaultdict(list)       # the words of a title -> the paths that carry them


def query_key(title):
    """What a list's title is about: no brand, no counts in brackets, "&" as "and", the words in a fixed order. Numbers stay, so
    "$25 an hour" and "$50 an hour" are different queries."""
    t = re.sub(r"\([^)]*\)", " ", title.rsplit(" | ", 1)[0].lower()).replace("&", " and ")
    # the counts after a colon are not words of the query either: "Customer Service Jobs in Austin: 50 Open, 5 New This Week" and the
    # skill list "Customer Service Jobs in Austin: 31 Open, 2 New" are one search (26 Nov 2026, when place lists took this form)
    t = re.sub(r":\s*[\d,]+ open(?:,\s*[\d,]+ new(?: this week)?)?\s*$", " ", t)
    return " ".join(sorted(w for w in re.findall(r"[a-z0-9$+#.]+", t) if w != "and"))


def one_page_per_query():
    """Runs when every page is written, before crosslinks.py: decides which page of each group keeps the search and returns
    {page that gives it up: the page that keeps it}. Links must lead to the page that keeps it (owner, 26 Nov 2026: "никакой
    каннибализации", the site grows by its links): CAT_HOME holds the pairs known while the pages are made (set_cat_home, the crypto
    lists), so finish_html wrote those links right. A pair found only here gets the same rule now, and the pages already written are
    mended in one pass; the build says which, so the pair can be named where its pages are made and the pass is not needed."""
    rank = {s_: i for i, s_ in enumerate(SAME_QUERY_ORDER)}
    moved = {}
    for key, paths in SAME_QUERY.items():
        paths = [p_ for p_ in dict.fromkeys(paths) if (OUT / p_ / "index.html").exists()]
        if len(paths) < 2: continue
        paths.sort(key=lambda p_: (rank[p_.split("/", 1)[0]], len(p_), p_))
        for p_ in paths[1:]: moved[p_] = paths[0]
    # Twins by address (26 Nov 2026): the same jobs of the last three days stand at /skills/<skill>/new/ and at /new/skills/<skill>/ (and the
    # same for a kind of work). Their titles differ, so the words above do not catch them; the /new/ list, with its own rows and links, keeps the search.
    for sec_ in ("skills", "roles"):
        d_ = OUT / sec_
        if not d_.is_dir(): continue
        for x_ in sorted(d_.iterdir()):
            if (x_ / "new" / "index.html").exists() and (OUT / "new" / sec_ / x_.name / "index.html").exists():
                moved[f"{sec_}/{x_.name}/new/"] = f"new/{sec_}/{x_.name}/"
    # The page that keeps a search may hand it on in turn: /roles/supply-chain/ ("Supply Chain and Logistics Jobs") gave it to
    # /jobs/supply-chain/, which names /categories/logistics-transport/ (26 Nov 2026, a canonical that pointed at a page with another
    # canonical, on the live site too). The page at the end of the chain keeps it.
    def last(k_, p_):
        seen = {p_}
        while k_.rstrip("/") in CAT_HOME and k_ not in seen and (OUT / CAT_HOME[k_.rstrip("/")] / "index.html").exists():
            seen.add(k_); k_ = CAT_HOME[k_.rstrip("/")]
        return k_
    moved = {p_: k_ for p_, k_ in ((p_, last(k_, p_)) for p_, k_ in moved.items()) if k_ != p_}
    late = {p_: k_ for p_, k_ in moved.items() if CAT_HOME.get(p_.rstrip("/")) != k_}
    if late:
        print("one page per query: links mended after the build, name these where the pages are made: " + ", ".join(f"/{p_} -> /{k_}" for p_, k_ in sorted(late.items())))
        for p_, k_ in late.items(): same_as(p_.rstrip("/"), k_)
        for dir_, _, files_ in os.walk(OUT):
            if "index.html" not in files_ or os.path.relpath(dir_, OUT).split(os.sep, 1)[0] == "job": continue
            f = Path(dir_) / "index.html"
            t_ = f.read_text(encoding="utf-8")
            if any(f'/{p_}"' in t_ for p_ in late):
                f.write_text(CAT_HOME_RX[0].sub(lambda m: CAT_HOME[m.group(1)], t_), encoding="utf-8")
    return moved


MAIN_RX = re.compile(r"<main[^>]*>(.*)</main>", re.S)
DATES_FILE = ROOT / "data" / "lastmod.json"


def page_dates(urls):
    """{page: the day its text last changed} for the pages of urls that are no list of jobs (PAGE_MOD holds those): a guide, a tool, a
    glossary entry, a resume example, a comparison. What counts is the visible text of <main> with every figure taken out, so a count or
    a median recounted every hour is not a change, and a new paragraph, a new row or a new link is. The fingerprint of each page and the
    day it last changed are kept in data/lastmod.json (the workflow carries the file from run to run); a page seen for the first time,
    or one whose file is missing, counts as changed today. A missing or damaged file is treated as empty."""
    try: old_ = json.loads(DATES_FILE.read_text(encoding="utf-8")) if DATES_FILE.is_file() else {}
    except (OSError, ValueError): old_ = {}
    if not isinstance(old_, dict): old_ = {}
    new_, out_ = {}, {}
    for u in urls:
        if u in PAGE_MOD:
            out_[u] = PAGE_MOD[u]; continue
        f = OUT / u / "index.html" if not u.endswith((".html", ".xml", ".txt", ".json")) else OUT / u
        try: t_ = f.read_text(encoding="utf-8", errors="replace")
        except OSError: continue
        m_ = MAIN_RX.search(t_)
        txt_ = re.sub(r"<script.*?</script>|<style.*?</style>", " ", m_.group(1) if m_ else t_, flags=re.S)
        txt_ = " ".join(re.sub(r"[\d,.%$€£¥₹+−-]+", " ", html.unescape(re.sub(r"<[^>]+>", " ", txt_))).split())
        h_ = hashlib.md5(txt_.encode("utf-8", "replace")).hexdigest()[:12]
        was_ = old_.get(u)
        day_ = was_[1] if isinstance(was_, list) and len(was_) == 2 and was_[0] == h_ and re.fullmatch(r"\d{4}-\d\d-\d\d", str(was_[1])) else TODAY
        new_[u] = [h_, day_]; out_[u] = day_
    try:
        DATES_FILE.parent.mkdir(parents=True, exist_ok=True)
        DATES_FILE.write_text(json.dumps(new_, separators=(",", ":")), encoding="utf-8")
    except OSError as ex:
        print(f"page dates: could not keep {DATES_FILE.name}: {ex}")
    kept_ = sum(1 for u, (h_, d_) in new_.items() if d_ != TODAY)
    print(f"page dates: {len(out_) - len(new_):,} lists dated by their newest job; {len(new_):,} other pages, {kept_:,} unchanged since an earlier day")
    return out_


def name_canonicals(moved):
    """The pages that give up a search name the page that keeps it as canonical and leave the sitemap. Returns how many."""
    n_ = 0
    for p_, keep in moved.items():
        f = OUT / p_ / "index.html"
        page_ = f.read_text(encoding="utf-8")
        own = f'<link rel="canonical" href="{e(FULL + "/" + p_)}">'
        if own not in page_: continue
        f.write_text(page_.replace(own, f'<link rel="canonical" href="{e(FULL + "/" + keep)}">', 1), encoding="utf-8")
        if p_ in URLS: URLS.remove(p_)
        n_ += 1
    return n_
