FT_RX, OTHER_TYPE_RX = re.compile(r"\bfull[- ]time\b", re.I), re.compile(r"\bpart[- ]time\b|\bcontract (?:role|position|basis|assignment|job|work)\b|\bcontract[- ]to[- ]hire\b|"
                                                                 r"\bcontractors?\b|\bfixed[- ]term\b|\btemporary\b|\bfreelance\b|\bseasonal\b|\binternships?\b", re.I)
# "Employment type: Part-time", "Job Type: Contract", Workday's "Time Type: Full time" in the text of the posting
ET_LABEL = re.compile(r"\b(?:employment|job|position|work|role|worker|time|contract|engagement)[ _-]?type\s*[:–-]?\s*(full[- ]?time|part[- ]?time|contractor|contract|"
                      r"temporary|fixed[- ]term|freelance|seasonal|internship|intern)\b", re.I)
FT_POS_RX = re.compile(r"\bfull[- ]time\s+(?:position|role|job|opportunity|employment opportunity|salaried position|exempt position|permanent position|w-?2 position)\b"
                       r"|\b(?:this|the|a)\s+(?:is\s+a\s+)?full[- ]time,?\s+(?:permanent|exempt|salaried|regular)\b", re.I)
ET_LABEL_LD = (("full", "FULL_TIME"), ("part", "PART_TIME"), ("contract", "CONTRACTOR"), ("freelance", "CONTRACTOR"), ("temporary", "TEMPORARY"),
               ("fixed", "TEMPORARY"), ("seasonal", "TEMPORARY"), ("intern", "INTERN"))


def etype_ld(j, full):
    """employmentType of a JobPosting, only from what the posting says: the feed's own field or the title (collect.etype), a label in the
    text ("Employment type: Part-time"), or "full-time" in the first part of a text that names no other kind of work. None when it says nothing."""
    if j.get("etype") in ETYPE_LD: return ETYPE_LD[j["etype"]]
    if not full: return None
    # Each pattern runs only when the words it needs are in the text (in lower case): the same answers on every posting of the local
    # record, a fraction of the time (26 Nov 2026: 416 µs a job before; the XML feed asks this of every open job). A tag cannot make
    # "type" or "full", so the test on the raw text is safe.
    low, plain_ = full.lower(), None
    if "type" in low:
        plain_ = re.sub(r"<[^>]+>", " ", full)
        m = ET_LABEL.search(plain_) if label_near(plain_.lower()) else None
        if m: return next(v for k, v in ET_LABEL_LD if m.group(1).lower().startswith(k))
    if "full" not in low or "time" not in low: return None
    if ("full-time" in low or "full time" in low) and FT_RX.search(full[:4000]) and not other_type(j["title"] + " " + full[:4000]): return "FULL_TIME"
    # further down, only a sentence about this job itself ("The salary range for this full-time position", "This is a full-time,
    # exempt role"), never "benefits for full-time employees", and only when the whole text names no other kind of work
    # (owner, 25 Nov 2026: Search Console still listed employmentType as missing on 9 pages; about 1% more jobs get it this way)
    plain_ = plain_ if plain_ is not None else re.sub(r"<[^>]+>", " ", full)
    low_ = plain_.lower()
    if ("full-time" in low_ or "full time" in low_) and FT_POS_RX.search(plain_) and not other_type(j["title"] + " " + full): return "FULL_TIME"
    return None


ET_WORDS = tuple(w_ + s_ for w_ in ("employment", "job", "position", "work", "role", "worker", "time", "contract", "engagement") for s_ in ("", " ", "_", "-"))


def label_near(low):
    """Whether "type" follows one of ET_LABEL's words anywhere in the lower-case text: ET_LABEL cannot match without it."""
    i = low.find("type")
    while i >= 0:
        if low[max(0, i - 12):i].endswith(ET_WORDS): return True
        i = low.find("type", i + 1)
    return False


OTHER_TYPE_WORDS = ("part-time", "part time", "contract", "fixed-term", "fixed term", "temporary", "freelance", "seasonal", "internship")


def other_type(text):
    """OTHER_TYPE_RX.search(text), run only when a word it needs is in the text."""
    low = text.lower()
    return any(w in low for w in OTHER_TYPE_WORDS) and OTHER_TYPE_RX.search(text)


# baseSalary only from pay the posting states (never an estimate), as collect.tidy_pay writes it
PAY_CUR = {"$": "USD", "US$": "USD", "CA$": "CAD", "A$": "AUD", "£": "GBP", "€": "EUR"}
PAY_UNIT = {"an hour": "HOUR", "a day": "DAY", "a week": "WEEK", "a month": "MONTH"}
_PC = r"US\$|CA\$|A\$|\$|£|€|[A-Z]{3} "
PAY_LD_RX = re.compile(rf"^({_PC})(\d[\d,]*(?:\.\d+)?)(K?)(?: ?[-–] ?(?:{_PC})?(\d[\d,]*(?:\.\d+)?)(K?))?(?: (an hour|a day|a week|a month))?$")
DOLLAR_LANDS = {"CA", "AU", "NZ", "SG", "HK", "MX", "AR", "CL", "CO", "TW"}       # a bare "$" there may be the local dollar or peso


def pay_ld(j):
    """baseSalary (MonetaryAmount) from the pay a posting states: "$152K - $239K" a year, "£45K - £55K", "$38 - $55 an hour",
    "€3,000 - €4,000 a month", "SGD 100K - SGD 120K"; None for anything else. Before 22 Nov 2026 only yearly US-dollar ranges were
    marked up, and Search Console listed baseSalary as missing on pages that showed pounds, euros or an hourly rate."""
    m = PAY_LD_RX.match((j.get("salary") or "").strip())
    if not m: return None
    if m.group(1) == "$":
        lands = {c for c, _ in countries_of(j.get("location") or "")}
        if lands and lands <= DOLLAR_LANDS: return None
    num = lambda v, k: float(v.replace(",", "")) * (1000 if k else 1)
    lo = num(m.group(2), m.group(3))
    hi = num(m.group(4), m.group(5)) if m.group(4) else lo
    unit = PAY_UNIT.get(m.group(6) or "", "YEAR")
    if not 0 < lo <= hi or (unit == "YEAR" and lo < 10000): return None
    n = lambda v: int(v) if v == int(v) else round(v, 2)
    val = {"@type": "QuantitativeValue", **({"value": n(lo)} if hi == lo else {"minValue": n(lo), "maxValue": n(hi)}), "unitText": unit}
    return {"@type": "MonetaryAmount", "currency": PAY_CUR.get(m.group(1)) or m.group(1).strip(), "value": val}
for _pay, _want in {"$152K - $239K": ("USD", 152000, 239000, "YEAR"), "£45K - £55K": ("GBP", 45000, 55000, "YEAR"), "$38 - $55 an hour": ("USD", 38, 55, "HOUR"),
                    "€3,000 - €4,000 a month": ("EUR", 3000, 4000, "MONTH"), "SGD 100K - SGD 120K": ("SGD", 100000, 120000, "YEAR"), "CA$90K - CA$110K": ("CAD", 90000, 110000, "YEAR")}.items():
    _v = pay_ld({"salary": _pay, "location": "London"})["value"]
    assert (pay_ld({"salary": _pay})["currency"], _v["minValue"], _v["maxValue"], _v["unitText"]) == _want, (_pay, _v)
assert pay_ld({"salary": "$0 - $125 an hour"}) is None and pay_ld({"salary": "$150K - $180K", "location": "Toronto, ON"}) is None and pay_ld({"salary": "$50 - $60"}) is None


def sane_pay(s):
    """The pay a posting states, or "" when the range cannot be one person's pay (owner, 25 Nov 2026: the home page's "Highest paid
    right now" showed "Desktop Support Technician $90K–$1,100K", "PMH Nurse Practitioner $100K–$1,500K", "Business Broker
    $50K–$1,000K"): a top more than three times the bottom, a bottom of nothing, or a yearly US-dollar figure above $900K. Used when
    the build reads the records and again on every job page (the server renders the pages of jobs found between uploads), so neither
    the text nor baseSalary carries such a range. collect.tidy_pay is left as it is: any edit there changes its RULES fingerprint and
    makes the hourly run parse every posting again."""
    m = PAY_LD_RX.match((s or "").strip())
    if not m: return s or ""
    num = lambda v, k: float(v.replace(",", "")) * (1000 if k else 1)
    lo = num(m.group(2), m.group(3))
    hi = num(m.group(4), m.group(5)) if m.group(4) else lo
    if lo <= 0 or hi > 3 * lo: return ""
    if not m.group(6) and m.group(1).strip() in ("$", "US$", "USD") and hi > 900000: return ""
    return s
assert sane_pay("$90K - $1,100K") == sane_pay("$100K - $1,500K") == sane_pay("$50K - $1,000K") == sane_pay("$0 - $125 an hour") == sane_pay("$850K - $950K") == ""
assert sane_pay("$152K - $239K") == "$152K - $239K" and sane_pay("SEK 554K - SEK 1,025K") == "SEK 554K - SEK 1,025K" and sane_pay("$38 - $55 an hour") == "$38 - $55 an hour" and sane_pay("") == ""


