SLUG_ICON = {   # fields on /categories/ and the categories of job lists
    "software-development": "code", "ai-machine-learning": "spark", "data-analytics": "chart", "cloud-devops-it": "cloud", "security": "shield", "product-project": "board",
    "design-creative": "pen", "marketing-communications": "megaphone", "sales": "trend", "customer-service": "headset", "accounting-finance": "coin", "legal-compliance": "scales",
    "hr-recruiting": "users", "operations-administration": "sliders", "hardware-engineering": "chip", "writing-translation": "text", "science-healthcare": "heart",
    "education-training": "cap", "retail-hospitality": "bag", "languages": "globe", "skilled-trades": "factory", "logistics-transport": "box", "crypto-web3": "hex", "leadership": "crown", "internships-entry-level": "sprout",
    "engineering": "code", "product": "board", "design": "pen", "sales-bd": "trend", "marketing": "megaphone", "support": "headset", "compliance-legal": "scales", "finance": "coin",
    "people": "users", "data-research": "chart", "operations": "sliders", "healthcare": "heart", "manufacturing": "factory", "supply-chain": "box", "retail": "bag",
    "education": "cap", "consulting": "case", "other": "dots",
}
PATH_FIELD = re.compile(r"^(?:jobs|crypto|categories|salaries)/([a-z0-9-]+)/$")


def icon(slug):
    """The field's icon in a soft square, or nothing when the slug is not a field."""
    name = SLUG_ICON.get(slug)
    return f'<span class="fic"><svg viewBox="0 0 24 24" aria-hidden="true">{ICON[name]}</svg></span>' if name else ""


def path_icon(path):
    m = PATH_FIELD.match(path)
    return icon(m.group(1)) if m else ""


def card(j, extra=0):
    b = []
    # where a job not read from the employer's own hiring system comes from (teardown, 26 Nov 2026: "only from employers' own pages")
    if j.get("tg"): b.append('<span class="pill" title="A post in a public Telegram job channel, not checked with the employer">Telegram post</span>')
    elif str(j.get("id") or "").startswith("usajobs-"): b.append('<span class="pill" title="A federal job, read from USAJOBS, the US government’s official job site">USAJOBS</span>')
    if j["featured"]: b.append('<span class="pill acc">Featured</span>')
    if j.get("urgent"): b.append('<span class="pill urg">Urgently hiring</span>')
    if not j["active"]: b.append('<span class="pill">Closed</span>')
    if j["remote"]: b.append('<span class="pill ok">Remote, anywhere</span>' if j.get("anywhere") else '<span class="pill ok">Remote</span>')   # how the work is done
    elif j.get("hybrid"): b.append('<span class="pill">Hybrid</span>')
    if j["level"]: b.append(f'<span class="pill">{e(LVL_NAME[j["level"]])}</span>')
    b += [f'<span class="pill">{e(t)}</span>' for t in j["tags"][:3]]
    loc = j["location"] if len(j["location"]) <= 60 else j["location"][:57].rstrip(" ,;") + "…"
    sub = e(j["company"]) + (f" · {loc_flags(j['location'])}{e(loc)}" if loc else "") + (f" · +{extra} more location{'s' if extra > 1 else ''}" if extra else "")
    label, fresh = age(j["posted"])
    return (f'<li class="job{" feat" if j["featured"] else ""}"><a href="{P}/job/{j["slug"]}/">{ava(j["company"])}'
            f'<span><span class="jt">{e(j["title"])}</span><span class="js">{sub}</span></span>'
            f'<span class="jr"><span class="jp{"" if j["salary"] else " none"}">{e(pay_shown(j["salary"])[:28]) if j["salary"] else "—"}</span><span class="pills">{"".join(b)}</span><time {when(j)}{" class=\"new\"" if fresh and j["active"] else ""}>{label}</time></span></a></li>')


def eg(html):
    """An example card on a sales page: it must not look or act like a link (a click on `#` only threw the visitor to the top)."""
    return html.replace(f'<a href="{P}/job//">', '<a class="eg">')


def tile(url, name, count, avatar=False):
    return f'<li><a class="tile" href="{P}/{url}">{ava(name, "sm") if avatar else ""}{path_icon(url)}<span class="n">{path_fl(url)}{e(name)}</span><span class="c">{count:,}</span></a></li>'


def tw(title):
    """A two-weight headline: the words inside [[ ]] are bold, the rest is set light ("Where the [[most jobs]] are")."""
    return e(title).replace("[[", "<b>").replace("]]", "</b>")


def section(title, inner, link=None, sid="", sub="", label=""):
    """A titled block. `sub` is one plain sentence beside the heading (heading left, sentence and the link right).
    `label` (the main sections of hub pages): a small label above the title, and the title in two weights, see tw().
    Without a label the markup is what it always was: with_toc() and the job pages read it."""
    more = f'<a href="{P}/{link[0]}">{e(link[1])}</a>' if link else ""
    sb = f'<p class="sec-sub">{e(sub)}</p>' if sub else ""
    sid_ = f" id={chr(34)}{sid}{chr(34)}" if sid else ""
    if label:
        # v4: a labelled title written without [[ ]] was set all light; it gets its two weights the way sec_labels() gives them
        t_ = tw(title) if "[[" in title else (two_weight(e(title)) or f"<b>{e(title)}</b>")
        return (f'<section class="sec hsec"{sid_}><div class="sec-head"><div class="sec-ttl"><p class="sec-label">{e(label)}</p><h2 class="tw">{t_}</h2></div>'
                f'{sb}{more}</div>{inner}</section>')
    return f'<section class="sec"{sid_}><div class="sec-head{" has-sub" if sub else ""}"><h2>{e(title)}</h2>{sb}{more}</div>{inner}</section>'


def fx(dl):
    """The figures row of a page of the 391-page families (a facts list) drawn as the framed row of numbers the hubs use, with the line that says when they were checked."""
    return dl.replace('<dl class="facts">', '<dl class="nums">') + f'<p class="nums-src"><a href="{P}/methodology/">Checked {fdate(TODAY, False)} against employer career pages</a></p>'


def pics_first(pics, block):
    """Pictures above a block on wide screens and under it on a phone (the same two classes listing() uses for the charts and the list)."""
    return f'<div class="lflow"><div class="lpics">{pics}</div><div class="llist">{block}</div></div>' if pics else block


def nums(cells, src=True):
    """One row of a page's own numbers: [(value, label)]; a label may hold a link. Counted in the build, never typed in.
    `src`: the line under the row that says when the figures were checked and against what."""
    if not cells: return ""
    return ('<dl class="nums">' + "".join(f"<div><dt>{b}</dt><dd>{a}</dd></div>" for a, b in cells) + "</dl>"
            + (f'<p class="nums-src"><a href="{P}/methodology/">Checked {fdate(TODAY, False)} against employer career pages</a></p>' if src else ""))


# The key pages (home, search, employers, pricing, Plus, about; 17 Nov 2026). <main> carries "kp" and the page's own word; the styles
# are the last block of style.css. The way of building is the one of DESIGN_STUDY.md, "dLocal and Ashby", in our colours: a few
# framed panels instead of a long sheet, a label above a two-weight headline, one pill button a block, rows that open.
def go(href, label, kind="primary"):
    """The one action of a block: a pill button with its arrow in a circle. `kind`: "primary" (ink) or "ghost" (an outline)."""
    u = href if href.startswith(("#", "http")) else f"{P}/{href}"
    return f'<a class="btn {kind} go" href="{u}">{e(label)}<i aria-hidden="true"></i></a>'


def kpanel(sec, kind="soft"):
    """A section() set in a frame with a large corner radius: "soft" (a tinted panel), "card" (white, with a border), "ink" (dark;
    its buttons are paper). The dark kind is not used: the owner saw it on the home page on 17 Nov 2026 and wrote "the light one
    seems better to me", so the panels for employers on the home page, on /post-a-job/ and on /plus/ are "soft"."""
    return sec.replace('<section class="sec hsec"', f'<section class="sec hsec kpanel {kind}"', 1)


def khero(trail, label, h1, lead, actions="", after=""):
    """The first screen of a key page as one framed panel: the trail, a label, the H1, the opening paragraph, the action, then
    `after` (a row of figures, a note). `h1` and `lead` are HTML."""
    return (f'<div class="khero"><div class="khero-t">{trail}<p class="sec-label">{e(label)}</p><h1>{h1}</h1><p class="lead">{lead}</p>{actions}</div>'
            f'{after}</div>')


def krows(rows, name):
    """Rows that open, one at a time: [(title, what stands beside it, the block inside as HTML)]. The first row is open."""
    return ('<div class="krows">' + "".join(
        f'<details name="{name}"{" open" if i == 0 else ""}><summary><b>{e(t_)}</b><span>{e(s_)}</span></summary><div class="krow-in">{inner}</div></details>'
        for i, (t_, s_, inner) in enumerate(rows)) + "</div>")


def kmore(title, inner):
    """A long table kept one click away: closed until asked for, so the page reads as a few blocks and nothing is lost."""
    return f'<details class="kmore"><summary><span>{e(title)}</span></summary>{inner}</details>'


def kcta(label, h2, text, actions, gets=(), kind="soft", sid=""):
    """A panel in two parts, the markup of the home page's band for employers (sections review, batch 5: the single pages end
    with it): a label, a two-weight headline ([[ ]] marks the bold words), one paragraph (HTML) and the action on the left;
    `gets`, a short ruled list (HTML items), on the right. Without `gets` the text takes the whole width."""
    return (f'<section class="sec hsec kpanel {kind} kcta{"" if gets else " one"}"' + (f' id="{sid}"' if sid else "") + f'><div class="kcta-t"><p class="sec-label">{e(label)}</p>'
            f'<h2 class="tw">{tw(h2)}</h2><p>{text}</p><p class="kact">{actions}</p></div>'
            + ('<ul class="kgets">' + "".join(f"<li>{g_}</li>" for g_ in gets) + "</ul>" if gets else "") + "</section>")


def bump_stamp(at):
    """The moment a "Bump to top" was bought, as a timestamp for sorting; 0 when there is none."""
    try:
        return int(datetime.datetime.fromisoformat(str(at).replace("Z", "+00:00")).timestamp()) if at else 0
    except Exception:
        return 0


STALE_DAY = (datetime.date.today() - datetime.timedelta(days=LONG_OPEN)).isoformat()


def month_of(day):
    """'2023-01-31' -> 'Jan 2023' (the day itself when it is not a date)."""
    try: return datetime.date.fromisoformat(day[:10]).strftime("%b %Y")
    except Exception: return day


def stale(j):
    """A talent pool, or a posting its employer dated LONG_OPEN (90) or more days ago. Lists show these after every fresh opening, the
    search leaves them out unless asked (assets/app.js, old=1), and their page does not say "Hiring now". Teardown, 26 Nov 2026: the
    newest-first order went by the hour we first read a job, so a board read for the first time this week put its postings from 2021-2023
    at the top of "nurse" and "customer service" with "Hiring now" and "Open for 2,073 days"."""
    return bool(j.get("pool")) or bool(j.get("posted")) and j["posted"][:10] < STALE_DAY


def order(jobs):
    """Paid first, then the newest; roles open 90+ days, talent pools and the jobs of boards that repost most of their jobs every week
    (CHURN) after all the others (stale()). Premium jobs lead and take turns: their order changes with every build (the seed is the day and
    the number of open jobs, so one build and the records made from it agree), which is the "turn in the top 3" a Premium boost
    promises when a list holds more than three of them. A bumped job is as new as its bump."""
    seed = f"{TODAY}-{ALL_OPEN[0]}-"
    return sorted(jobs, key=lambda j: (not j.get("premium"), hashlib.md5((seed + j["slug"]).encode()).hexdigest() if j.get("premium") else "", not j.get("pinned"), not j["featured"],
                                       stale(j) or j["company"] in CHURN, -max(j.get("ts") or stamp(j), j.get("bump") or 0)))


def diverse(jobs, k, per=2):
    """First k jobs with at most `per` from the same company, so one big employer does not fill a list."""
    seen, out = Counter(), []
    for j in jobs:
        if seen[j["company"]] < per:
            seen[j["company"]] += 1; out.append(j)
            if len(out) == k: break
    return out


def diverse_pairs(pairs, k, per=2):
    seen, out = Counter(), []
    for j, r in pairs:
        if seen[j["company"]] < per:
            seen[j["company"]] += 1; out.append((j, r))
            if len(out) == k: break
    return out


def collapse(jobs):
    """The same role posted once per city becomes one row: [(job, number of extra postings)]. The role is the title without the store,
    mall or town an employer appends at each address (search_engine.role_key, the search's own rows: "+N more locations")."""
    first, out = {}, []
    for j in jobs:
        k = (j["company"], j.get("rkey") or search_engine.role_key(j["title"], j.get("location") or ""))
        if k in first: out[first[k]][1] += 1
        else:
            first[k] = len(out); out.append([j, 0])
    return out


def crumbs_ld(parts):
    items = [{"@type": "ListItem", "position": 1, "name": "Home", "item": FULL + "/"}]
    items += [{"@type": "ListItem", "position": i + 2, "name": n, **({"item": f"{FULL}/{u}"} if u else {})} for i, (n, u) in enumerate(parts)]
    return ('<script type="application/ld+json">' + json.dumps({"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": items},
                                                                 ensure_ascii=False).replace("</", "<\\/") + "</script>")


# Search Console, 25 Nov 2026: 23 of the 26 guides were "URL unknown to Google": they were linked only from /guides/ and from each
# other. Indexed list and tool pages now link the guides that belong to them. Only guides that are always built (advice_pages and the
# data guides written on every build) are named, so a link never leads nowhere.
GUIDES_ALWAYS = {"remote-jobs-by-field", "entry-level-jobs", "job-levels-explained", "is-this-job-still-open", "how-to-read-a-job-posting", "follow-up-after-applying"}


def guide_row(items, label="Guides"):
    import advice_pages
    ok_ = GUIDES_ALWAYS | {a_["slug"] for a_ in advice_pages.ARTICLES}
    return labrow(label, [f'<a href="{P}/guides/{s_}/">{e(t_)}</a>' for s_, t_ in items if s_ in ok_])


def labrow(label, items, more=None):
    """A labelled row: the label on the left, the links on the right, an optional "More" link last."""
    if not items: return ""
    tail = f'<a class="more" href="{P}/{more[0]}">{e(more[1])}</a>' if more else ""
    return f'<div class="lrow"><b>{e(label)}</b><div>{"".join(items)}{tail}</div></div>'


def kind_row(path):
    """The "Related lists" row of a list of a kind of work (KIND_REL), each link with its count of open jobs."""
    xs = [(u_, *KIND_N[u_]) for u_ in KIND_REL.get(path, ()) if u_ in KIND_N and u_ != path]
    return labrow("Related lists", [f'<a href="{P}/{u_}">{e(l_)} <b>{n_:,}</b></a>' for u_, l_, n_ in xs]) if len(xs) >= 2 else ""


def every_list(title, entries, groups):
    """Every narrower list under one page, grouped, with no cap (internal links, owner 18 Nov: "a link that boosts every page"):
    rel() shows the 14 largest, so the small lists of a big city were reached from nowhere. entries: [(path, label, count)];
    groups: [(label, regex on the path)], the first group that matches takes the entry.
    A list under the line (THIN: noindex, out of the sitemap) is left out (26 Nov 2026, Bing's guidelines on links and low-value
    addresses): the block was there to make search engines find the small lists, and these are no longer offered to them. Each is still
    linked from its neighbours ("Next to it") and from "Narrow down ..." (crosslinks.py), and the search has its jobs."""
    kept_ = [x for x in entries if x[0] not in THIN]
    EVERY_CUT.append((title, len(kept_), len(entries) - len(kept_)))
    entries = kept_
    seen, rows = set(), ""
    for label, rx in groups:
        xs = [x for x in entries if x[0] not in seen and re.search(rx, x[0])]
        seen |= {x[0] for x in xs}
        if xs: rows += labrow(label, [f'<a href="{P}/{u}">{e(t)} <b>{n:,}</b></a>' for u, t, n in sorted(xs, key=lambda x: -x[2])])
    return section(title, rows) if rows else ""


def rel(links, more=None):
    """Row of related listing links: [(path, label, count)], biggest first; `more` = (path, label) of the full directory."""
    links = sorted(links, key=lambda x: -x[2])[:14]
    return labrow("Related", [f'<a href="{P}/{u}">{e(t)}</a>' for u, t, _ in links], more)


def crumbs(*parts):
    items = [f'<a href="{P}/">Home</a>'] + [f'<a href="{P}/{u}">{e(n)}</a>' if u else e(n) for n, u in parts]
    return f'<div class="crumbs">{" / ".join(items)}</div>'


def rss_date(j):
    try: return "<pubDate>" + format_datetime(datetime.datetime.fromisoformat((j["posted"] or j["first_seen"])[:10]).replace(tzinfo=datetime.timezone.utc)) + "</pubDate>"
    except Exception: return ""


def rss(path, title, link, jobs):
    now = format_datetime(datetime.datetime.now(datetime.timezone.utc))
    items = "".join(
        f"<item><title>{e(j['title'])} at {e(j['company'])}</title><link>{FULL}/job/{j['slug']}/</link><guid>{FULL}/job/{j['slug']}/</guid>{rss_date(j)}"
        f"<description>{e(((j['location'] + '. ') if j['location'] else '') + j['excerpt'])}</description></item>" for j in order(jobs)[:100])
    write(path, f'<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>{e(title)}</title><link>{FULL}/{link}</link>'
                f"<description>{e(title)}</description><lastBuildDate>{now}</lastBuildDate>{items}</channel></rss>", sitemap=False)


AI_TAGS = ("AI", "LLM", "Machine Learning", "PyTorch", "TensorFlow", "LangChain", "Computer Vision", "NLP")
ALL_OPEN = [0]          # every open job on the site, set once the jobs are read: "this field is 2.1% of all open jobs"


MIX_ = [0.0]          # share of the open jobs in technology work (engineering, security, product, data and research, design), set in main()


def mix_note(tech_tail, other_tail):
    """The caveat under figures counted here. Until mid-November 2026 most jobs on the site were at technology companies and the pages said
    so; by 24 Nov the largest fields were healthcare and technicians, and "Most employers here are technology companies" had become
    untrue on eight kinds of page. The sentence now follows the open jobs of the day."""
    if MIX_[0] >= 0.5:
        return f"{100 * MIX_[0]:.0f}% of the jobs here are in technology work, so {tech_tail}"
    return f"The jobs here are the ones employers publish on their own careers pages ({100 * MIX_[0]:.0f}% of them in technology work), so {other_tail}"


CTR_W = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "nine": 9, "twelve": 12, "eighteen": 18}
CTR_LEN = re.compile(r"\b(\d{1,2}|one|two|three|four|five|six|nine|twelve|eighteen)(?:\s*(?:-|to|–)\s*(\d{1,2}))?[\s-]*(months?|weeks?|years?)\b"
                     r"(?:\s+(?:fixed[- ]term|temporary|initial|full[- ]time|w2|hourly))?\s+(?:contract|assignment|engagement|position|role|project|term)"
                     r"|\b(?:contract|assignment|engagement)\s+(?:length|duration|term)?\s*(?:of|:|for|is)?\s*(?:an?\s+)?(?:initial\s+)?"
                     r"(\d{1,2}|six|twelve|three|nine)(?:\s*(?:-|to|–)\s*(\d{1,2}))?[\s-]*(months?|weeks?|years?)\b", re.I)


def ctr_len_note(jobs):
    """How long today's contract postings say they run ("12-month contract", "6 month fixed-term contract", "contract length: 3 months"),
    for the glossary's contract figure: Google's "How long do contract jobs usually last?" (People also ask, 24 Nov 2026), answered
    from the postings' own words. Lengths over three years are left out (a pension term, not a contract's length)."""
    mo_ = []
    for j in jobs:
        if j.get("etype") != "Contract": continue
        m = CTR_LEN.search((j.get("title") or "") + " . " + (j.get("desc") or ""))
        if not m: continue
        a, b, u = (m.group(1), m.group(2), m.group(3)) if m.group(1) else (m.group(4), m.group(5), m.group(6))
        a = int(a) if a.isdigit() else CTR_W[a.lower()]
        v = (a + int(b)) / 2 if b else a
        v = v if u.lower().startswith("month") else v * 12 if u.lower().startswith("year") else v / 4.33
        if 0 < v <= 36: mo_.append(v)
    if len(mo_) < 20: return ""
    top_ = [k for k, _ in Counter(round(x) for x in mo_).most_common(2)]
    say_ = lambda k: f"{k} month{'s' if k != 1 else ''}"
    return (f" {len(mo_):,} of them state how long the contract runs: the median is {say_(round(median(mo_)))}, and the lengths named most are "
            f"{say_(top_[0])}" + (f" and {say_(top_[1])}." if len(top_) > 1 else "."))


def faq_for(label, jobs, first=None, extra=()):
    """Questions people actually ask about a set of jobs, answered from today's data. Returns (html, json-ld)."""
    if len(jobs) < 5: return "", ""
    n_, r = len(jobs), sum(j["remote"] for j in jobs)
    week = (datetime.date.today() - datetime.timedelta(days=7)).isoformat()
    new7 = sum(1 for j in jobs if (j["posted"] or "") >= week)
    top = Counter(j["company"] for j in jobs).most_common(5)
    mids = sorted((lo + hi) / 2 for j in jobs if j.get("usd") for lo, hi in [j["usd"]])
    cap = label[0].upper() + label[1:]
    n_co = len(set(j["company"] for j in jobs))
    qa = [(f"How many {label} are open right now?",
           f"There are {n_:,} open {label}{f' at {n_co:,} companies' if n_co > 1 else ''} on {SITE} as of {fdate(TODAY)}.{f" {new7:,} of them were posted in the last seven days." if new7 else ""} The list is rebuilt several times a day from the employers' own careers pages.")]
    if first: qa.insert(0, first)
    qa[1:1] = list(extra)                       # questions only this page can answer (a company's own hiring, say)
    if len(top) > 1:
        qa.append((f"Which companies have the most {label}?",
                   "Right now the most openings are at " + ", ".join(f"{c} ({k:,})" for c, k in top[:-1]) + f" and {top[-1][0]} ({top[-1][1]:,}). The ranking changes as companies open and close roles."))
    if "remote" in label.lower():
        aw = sum(1 for j in jobs if j.get("anywhere"))
        lands_ = Counter(nm for j in jobs for _, nm in countries_of(j["location"] or "")).most_common(5)
        qa.append((f"Which countries are {label} open to?", ", ".join(f"{nm} ({k:,})" for nm, k in lands_) + f": the countries named most in the location lines of the {n_:,} open {label}; "
                   f"{aw:,} say anywhere or worldwide.")) if len(lands_) >= 2 else None
        qa.append((f"Can I do {label} from any country?",
                   (f"Mostly not. {aw:,} of the {n_:,} open {label} are listed as open worldwide; the rest are limited to certain countries or time zones, so check the location line of each job." if aw else
                    f"Mostly not. None of the {n_:,} open {label} is listed as open worldwide today; each is limited to certain countries or time zones, named in its location line.")))
    elif r < n_ and not re.search(r"\bhybrid\b", label, re.I):      # every work-from-anywhere job is remote, no hybrid job is (25 Nov 2026)
        qa.append((f"Are there remote {label}?",
                   (f"{r:,} of the {n_:,} open {label} ({100 * r / n_:.0f}%) are listed as remote. Remote roles are often limited to certain countries or time zones, so check the location line of each job."
                    if r else f"None of the {n_:,} open {label} are listed as remote at the moment. Remote roles appear here as soon as employers post them.")))
    for sym_, word_ in (("£", "pounds"), ("€", "euros")):
        lm_ = sorted(m_ for j in jobs if (m_ := local_mid(j.get("salary"), sym_)))
        if len(lm_) >= 10:
            qa.append((f"What do {label} pay in {word_}?", f"{len(lm_):,} of the open postings state a yearly range in {word_}: the median midpoint is {sym_}{median(lm_):,.0f}, and the middle half "
                       f"advertise {sym_}{lm_[len(lm_) // 4]:,.0f} to {sym_}{lm_[3 * len(lm_) // 4]:,.0f}. These are advertised ranges as each employer wrote them, not verified pay."))
    # a company page answers its own "Does <company> pay well?" (extra): the generic pay question under it repeated the same figures (25 Nov 2026)
    hrs = sorted((h_[0] + h_[1]) / 2 for j in jobs if (h_ := j.get("usd_h") if "usd_h" in j else usd_hourly(j.get("salary"))))
    if len(hrs) >= 15 and len(hrs) >= len(mids) and not any("pay" in q_.lower() for q_, _ in extra):
        # most of these postings state pay by the hour (data teardown, 26 Nov 2026: Google quoted "Retail and Store Jobs... The median
        # advertised salary is $132K", the store managers' yearly ranges, for work paid $16 to $22 an hour)
        qa.append((f"What do {label} pay?",
                   f"The median advertised pay is ${median(hrs):,.2f} an hour, based on {len(hrs):,} open roles that state an hourly rate in US dollars. The middle half of those "
                   f"roles advertise between ${hrs[len(hrs) // 4]:,.2f} and ${hrs[min(len(hrs) - 1, 3 * len(hrs) // 4)]:,.2f} an hour. These are advertised rates, not verified pay."))
    elif len(mids) >= 15 and not any("pay" in q_.lower() for q_, _ in extra):
        qa.append((f"What is the median salary of {label}?" if " pay " in f" {label} " else f"What do {label} pay?",
                   f"The median advertised salary is {money(median(mids))}, based on {len(mids):,} open roles that publish a yearly US-dollar range. The middle half of those roles advertise between "
                   f"{money(mids[len(mids) // 4])} and {money(mids[min(len(mids) - 1, 3 * len(mids) // 4)])}. These are advertised ranges, not verified pay. "
                   + mix_note("the figures run above the wider market for the same work.", "the figures can differ from the wider market for the same work.")))
    # What Google's "People also ask" asks about a field (checked 15 Nov 2026 for "data analyst jobs": "Is it hard to get a data analyst
    # job?", "Will AI replace data analysts?", "Is a data analyst still worth it in 2026?"), answered with today's counts, never opinion.
    yrs = sorted(j["years"] for j in jobs if j.get("years"))
    ent = sum(1 for j in jobs if j.get("entry"))
    # a company page asks its own "Is it hard to get hired at <company>?" (extra): a second, generic one read as a repeat (24 Nov 2026)
    if n_ >= 20 and (len(yrs) >= 10 or ent) and not any(q_.startswith("Is it hard to get") for q_, _ in qa):
        one_ = (art(label[:-5]) + " " + label[:-1]) if label.endswith(" jobs") else f"one of the {label}"     # "data analyst jobs" -> "a data analyst job"
        # an entry-level list said "75 of the 75 open entry-level jobs in Dublin (100%) are for beginners" (26 Nov 2026)
        qa.append((f"Is it hard to get {one_}?",
                   (f"All {n_:,} open {label} are junior roles or internships, meant for beginners." if ent == n_ else
                    f"{ent:,} of the {n_:,} open {label} ({100 * ent / n_:.0f}%) are for beginners: junior roles and internships.")
                   + (f" Of the {len(yrs):,} postings that state experience, the median asks for {yrs[len(yrs) // 2]} {'year' if yrs[len(yrs) // 2] == 1 else 'years'}." if len(yrs) >= 10 else "")
                   + ((f" {n_co:,} companies are hiring" + (f" and {new7:,} {'role was' if new7 == 1 else 'roles were'} posted in the last seven days" if new7 else "") + ".") if n_co > 1 else
                      (f" {new7:,} {'role was' if new7 == 1 else 'roles were'} posted in the last seven days." if new7 else "")) + " Matching your resume to the skills each posting names helps most; the free resume builder shows the match."))
    ai_ = Counter(t for j in jobs for t in j.get("tags", []) if t in AI_TAGS)
    k_ai = sum(1 for j in jobs if any(t in AI_TAGS for t in j.get("tags", [])))
    # 25 Nov 2026: "How is AI changing part-time jobs? 10 of the 587 (2%) ask for AI skills" and "Most often Machine Learning (2%), Jira
    # (1%), dbt (0%)" said nothing and read as machine text on lists far from tech; both questions now need a real share behind them.
    if n_ >= 20 and k_ai >= max(5, 0.05 * n_):
        qa.append((f"How is AI changing {label}?",
                   f"{k_ai:,} of the {n_:,} open {label} ({100 * k_ai / n_:.0f}%) ask for AI or machine-learning skills"
                   + (", most often " + ", ".join(t for t, _ in ai_.most_common(3)) + "." if ai_ else ".")
                   + (f" Employers still list {n_:,} such roles today at {n_co:,} companies." if n_co > 1 else "") + f" Counted from the postings' own text on {fdate(TODAY)}."))
    # "What are the 5 skills of customer service?", "What jobs can I get with Python?" (People also ask, 15 Nov 2026)
    sk_ = [(t, k) for t, k in Counter(t for j in jobs for t in j.get("tags", [])).most_common(5) if k >= max(3, 0.02 * n_)]
    if n_ >= 20 and len(sk_) >= 3:
        qa.append((f"What skills do {label} ask for?",
                   "Most often " + ", ".join(f"{t} ({100 * k / n_:.0f}%)" for t, k in sk_) + f" of the {n_:,} open postings, counted from their own text on {fdate(TODAY)}."))
    ti_ = Counter(short_title(j["title"]) for j in jobs)
    ti_ = [(t, k) for t, k in ti_.most_common(8) if k >= 2 and 3 <= len(t) <= 60][:5]
    if n_ >= 20 and len(ti_) >= 3:
        qa.append((f"Which job titles come up most in {label}?",
                   ", ".join(f"{t} ({k})" for t, k in ti_) + f": the most common titles among the {n_:,} open roles, without the level and place notes in brackets."))
    if n_ >= 20 and ALL_OPEN[0] and n_co > 1:        # one company's jobs: "in demand ... at 1 company" said nothing (25 Nov 2026)
        qa.append((f"Are {label} in demand in {TODAY[:4]}?",
                   f"{n_:,} {label} are open on {SITE} today at {n_co:,} {'company' if n_co == 1 else 'companies'}, "
                   # "0.0% of all 784,846 open jobs" on a list of 75 (26 Nov 2026)
                   + (f"{100 * n_ / ALL_OPEN[0]:.1f}% of all" if 100 * n_ / ALL_OPEN[0] >= 0.05 else "out of") + f" {ALL_OPEN[0]:,} open jobs here"
                   + (f"; {new7:,} were posted in the last seven days." if new7 else ".") + (f" The median advertised salary is {money(median(mids))}." if len(mids) >= 15 else "")
                   + f" {r:,} ({100 * r / n_:.0f}%) can be done remotely."))
    qa.append((f"How do I apply for {label}?",
               f"Open a job and press “Apply on company site”. You go straight to the employer's own careers page and apply there. {SITE} needs no account and charges nothing for applying."))
    seen_ = set()
    qa = [x for x in qa if not (x[0] in seen_ or seen_.add(x[0]))]       # a page's own question first: "Are there remote night shift jobs?" stood twice (25 Nov 2026)
    html_ = '<dl class="qa">' + "".join(f"<div><dt>{e(q)}</dt><dd>{e(a_)}</dd></div>" for q, a_ in qa) + "</dl>"
    ld = ('<script type="application/ld+json">' + json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a_}} for q, a_ in qa]}, ensure_ascii=False).replace("</", "<\\/") + "</script>")
    return section(f"Questions about {label}", html_), ld


def qa_sec(title, qa, label="", sid=""):
    """A block of questions and its FAQPage markup, for a page whose questions are written by hand: (html, json-ld)."""
    qa = [x for x in qa if x]
    if not qa: return "", ""
    html_ = '<dl class="qa">' + "".join(f"<div><dt>{e(q)}</dt><dd>{e(a_)}</dd></div>" for q, a_ in qa) + "</dl>"
    ld = ('<script type="application/ld+json">' + json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a_}} for q, a_ in qa]}, ensure_ascii=False).replace("</", "<\\/") + "</script>")
    return section(title, html_, sid=sid, label=label), ld


def pager_html(path, n, pages):
    if pages <= 1: return ""
    url = lambda i: f'{P}/{path}{"" if i == 1 else f"{i}/"}'
    keep = sorted({1, pages} | {i for i in range(n - 2, n + 3) if 1 <= i <= pages})
    out, prev = [], 0
    if n > 1: out.append(f'<a rel="prev" href="{url(n - 1)}">← Prev</a>')
    for i in keep:
        if i - prev > 1: out.append("<span>…</span>")
        out.append(f"<b>{i}</b>" if i == n else f'<a href="{url(i)}">{i}</a>')
        prev = i
    if n < pages: out.append(f'<a rel="next" href="{url(n + 1)}">Next →</a>')
    return f'<div class="pager">{"".join(out)}</div>'


CAT_ACCENT = {}                       # sections once had their own colours; the site now keeps one green everywhere
HUB = {"roles": {}, "week": "", "job_roles": {}}       # role slug -> (name, ids of its jobs); job id -> its role slugs; filled in main()
# How many templates the resume builder offers, counted from assets/resume.js (TPL_NAMES), so the copy cannot fall behind it again:
# it said "five" while the builder had six (20 Nov 2026).
_NUM_WORD = {3: "three", 4: "four", 5: "five", 6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten"}
_rb_m = re.search(r"TPL_NAMES = \{(.*?)\};", (ROOT / "assets" / "resume.js").read_text(), re.S)
RB_N = len(re.findall(r"(\w+): \[", _rb_m.group(1))) if _rb_m else 0
RB_TPLS = _NUM_WORD.get(RB_N, "several")


LIST_LABEL = {"jobs": "Field", "roles": "Kind of work", "skills": "Skill", "locations": "Place", "remote": "Remote work", "crypto": "Crypto and web3",
              "perks": "Perk", "salary": "Pay", "jobs-that-pay": "Hourly pay", "companies": "Company", "new": "New today", "entry-level": "First jobs",
              "internships": "Internships", "part-time": "Part-time", "contract": "Contract", "hybrid": "Hybrid", "tech": "Tech",
              "senior-jobs": "Level", "lead-jobs": "Level", "executive-jobs": "Level", "night-shift": "Shifts", "weekend": "Shifts",
              "summer": "Season", "temporary": "Season", "with-salary": "Pay stated", "work-from-anywhere": "Remote work",
              "hiring-immediately": "Hiring now", "no-experience-jobs": "First jobs", "fair-chance-jobs": "Fair chance", "categories": "Field"}


def list_label(path):
    """The small label above a list's heading: what kind of list it is ("Place", "Skill"), from its address."""
    seg = path.strip("/").split("/")
    if seg[0] == "locations" and len(seg) > 2: return {"remote": "Remote work", "skills": "Skill", "companies": "Companies"}.get(seg[2], "Place")
    if seg[0] == "roles" and len(seg) > 2: return "Kind of work"
    return LIST_LABEL.get(seg[0], "Jobs")


def h1_marked(h1):
    """The heading in two weights (v4, 25 Nov 2026, after dLocal): the common word and the link word after it are set light, the
    subject stays bold: "Engineering (jobs)", "(Internships in) Paris". It marked the common word in green before."""
    m = re.search(r"\b(?:jobs|internships|roles)\b(?:\s+(?:in|at|for|with|near|from|by|that)\b)?", h1, re.I)
    if not m: return e(h1)
    return e(h1[:m.start()]) + f'<span class="lt">{e(m.group(0))}</span>' + e(h1[m.end():])


def hub_stats(js, lead=False):
    """The headline numbers of a set of jobs, as a row of figures. `lead`: the paragraph above the row already says how many are open
    (that first sentence is what search engines and assistants quote), so the row holds the other figures only."""
    k = len(js)
    if k < 20: return ""
    mids = sorted((j["usd"][0] + j["usd"][1]) / 2 for j in js if j.get("usd"))
    week = sum(1 for j in js if (j['posted'] or '') >= HUB['week'])
    # a list that is all from the last week (/new/: the last three days) would read "N open roles, N posted in the last 7 days":
    # there the second figure is the last 24 hours instead (20 Nov 2026, found on /new/)
    fresh = (f"{sum(1 for j in js if NOW - (j.get('ts') or 0) <= 86400):,}", "posted in the last 24 hours") if week == k else (f"{week:,}", "posted in the last 7 days")
    cells = [(f"{k:,}", "open roles"), fresh,
             (f"{100 * sum(j['remote'] for j in js) / k:.0f}%", "remote"), (f"{len({j['company'] for j in js}):,}", "companies hiring")]
    if len(mids) >= 30: cells.append((money(median(mids)), f'<a href="{P}/glossary/median/">median</a> advertised salary'))
    if all(j["remote"] for j in js): cells = [c for c in cells if c[1] != "remote"]       # a list of remote jobs: "100% remote" says nothing
    if lead: cells = cells[1:]
    return nums(cells)


def hub_sections(label, js, skip="", min_k=40, drop_tag=""):
    """Who hires, which skills and roles, where, and what it pays at each level: the same set of jobs seen from five sides.
    skip: the sides a page already is ("places" on a London page; several joined by commas). drop_tag: the page's own skill."""
    k = len(js)
    if k < min_k: return "", ""
    plc = label[len("roles in "):] if label.startswith("roles in ") else ""      # a place page: "Job titles in London"
    top, out, ids = [], [], {j["id"] for j in js}
    bars = lambda rows_: '<div class="hbars">' + "".join(
        f'<a href="{P}/{u}"><span class="hn">{e(nm)}</span><span class="hb"><i style="width:{max(3, round(100 * c / rows_[0][2]))}%"></i></span><span class="hc">{c:,} · {100 * c / k:.0f}%</span></a>' for u, nm, c in rows_) + "</div>"
    if "skills" not in skip:
        # a skill named in under 2% of the jobs is noise on the chart ("Figma 1 · 0%" on the part-time list, 25 Nov 2026)
        sk = [(t, c) for t, c in Counter(t for j in js for t in j["tags"] if t != drop_tag).most_common(7) if c >= max(3, 0.02 * k)]
        if len(sk) >= 4: top.append(f'<div><h2 class="h2s">Skills asked for in {e(plc or label)}</h2>' + bars([(f"skills/{TAG_SLUG.get(t, slugify(t))}/", t, c) for t, c in sk]) + "</div>")
    if "roles" not in skip:
        # how many of this page's jobs each kind of work has: asked of the page's jobs, not of every role's whole set of jobs
        # (len(ids & rid) for 531 roles on each of thousands of pages was a large part of a build on the full record, 17 Nov 2026)
        rk = Counter(s_ for jid in ids for s_ in HUB["job_roles"].get(jid, ()))
        rl = sorted(((s_, nm, rk.get(s_, 0)) for s_, (nm, rid) in HUB["roles"].items()), key=lambda x: -x[2])
        rl = [x for x in rl if x[2] >= 8][:7]
        if len(rl) >= 3: top.append(f'<div><h2 class="h2s">Job titles in {e(plc or label)}</h2>' + bars([(f"roles/{s_}/", nm, c) for s_, nm, c in rl]) + "</div>")
    co = Counter(j["company"] for j in js).most_common(12) if "who" not in skip else []
    if len(co) >= 4: out.append(section(f"Who is hiring in {plc}" if plc else f"Who is hiring for {label}", '<ul class="tiles">' + "".join(tile(f"companies/{slugify(c)}/", c, n_, True) for c, n_ in co) + "</ul>"))
    if "places" not in skip:
        pname = {slug: name.removeprefix("the ") for name, slug, _ in PLACES}
        pl = [(p_, c) for p_, c in Counter(p_ for j in js for p_ in j["places"]).most_common(40) if p_ in HUB.get("live", ())][:10]
        if len(pl) >= 4: out.append(section(f"Where the {label} are" if label.startswith("roles ") else f"Where {label} are", '<ul class="tiles">' + "".join(tile(f"locations/{p_}/", pname[p_], c) for p_, c in pl) + "</ul>"
                                            + '<p class="note">A role that lists several places is counted in each of them.</p>'))
    lv = defaultdict(list)
    for j in js:
        if j.get("usd"): lv[LVL_NAME[j["level"]]].append((j["usd"][0] + j["usd"][1]) / 2)
    pay = {nm: (median(v), len(v)) for nm, v in lv.items() if len(v) >= 15}
    # in the posting's own currency too, where pounds or euros are stated often enough (plan item 1.5, 20 Nov 2026: a London page gave
    # pay by level in US dollars only, and the pounds only in a question at the foot)
    sym_ = max(("£", "€"), key=lambda c_: sum(1 for j in js if c_ in (j.get("salary") or "")))
    lv_l = defaultdict(list)
    for j in js:
        if (m_ := local_mid(j.get("salary"), sym_)): lv_l[LVL_NAME[j["level"]]].append(m_)
    pay_l = {nm: (median(v), len(v)) for nm, v in lv_l.items() if len(v) >= 10}
    if len(pay_l) < 2: pay_l = {}
    if len(pay) >= 2 or pay_l:
        order_ = {LVL_NAME[k]: i for i, k in enumerate(("Intern", "Junior", "", "Senior", "Lead"))}
        cur_ = "pounds" if sym_ == "£" else "euros"
        lv_rows = sorted(set(pay) | set(pay_l), key=lambda x: order_.get(x, 9))
        cell_ = lambda d_, nm, f_: f"<strong>{f_(d_[nm][0])}</strong> <span class=\"note\">({d_[nm][1]:,})</span>" if nm in d_ else "–"
        loc_money = lambda v: f"{sym_}{round(v / 1000)}K"
        out.append(section(f"What jobs in {plc} pay, by level" if plc else f"Pay by level: {label}" if " pay " in f" {label} " else f"What {label} pay, by level",
                           '<div class="tablewrap"><table><tr><th>Level in the title</th>' + ("<th>Median advertised salary, US dollars (roles)</th>" if len(pay) >= 2 else "")
                           + (f"<th>Median in {cur_} (roles)</th>" if pay_l else "") + "</tr>"
                           + "".join(f"<tr><td>{e(nm)}</td>" + (f"<td>{cell_(pay, nm, money)}</td>" if len(pay) >= 2 else "") + (f"<td>{cell_(pay_l, nm, loc_money)}</td>" if pay_l else "") + "</tr>" for nm in lv_rows)
                           + '</table></div><p class="note">Medians of the midpoints of advertised yearly ranges, each in the currency the posting states; a level needs at least 15 roles in US dollars'
                           + (f" or 10 in {cur_}" if pay_l else "") + '. Advertised, not verified pay.</p>'))
    ct_ = sum(1 for j in js if j.get("etype") == "Contract")
    if k >= 40 and ct_:
        out.append(f'<p class="note">{ct_:,} of these {k:,} roles ({round(100 * ct_ / k)}%) are listed as contract work by the employer; the rest are permanent or do not say.</p>')
    glance = (f'<div class="hubgrid">{"".join(top)}</div><p class="note">Bars show the share of these {k:,} roles; one role can count in several rows.</p>' if top else "")
    return glance, "".join(out)


def job_links(xs, n=8):
    """A few jobs of a set as plain links (title, then company), newest first."""
    return '<ul class="xl">' + "".join(f'<li><a href="{P}/job/{j["slug"]}/">{e(j["title"])}</a> <span>{e(j["company"])}</span></li>' for j in order(xs)[:n]) + "</ul>"


def auto_more(path, h1):
    """The search filters that reproduce a list page, for its "see all in search" link."""
    seg = path.strip("/").split("/")
    q = lambda v: quote(v)
    if seg[0] == "jobs" and len(seg) == 2: return f"cat={seg[1]}"
    if seg == ["remote"]: return "remote=1"
    if seg[0] == "remote" and len(seg) == 2 and seg[1] in CAT: return f"remote=1&cat={seg[1]}"
    if seg == ["crypto"]: return "crypto=1"
    if seg == ["crypto", "remote"]: return "crypto=1&remote=1"
    if seg[0] == "crypto" and len(seg) == 2: return f"crypto=1&cat={seg[1]}"
    if seg == ["with-salary"]: return "salary=1"
    if seg == ["entry-level"]: return "entry=1"
    if seg == ["new"]: return "age=3"
    if seg == ["work-from-anywhere"]: return "any=1&remote=1"
    if seg[0] == "locations" and len(seg) == 2: return f"loc={seg[1]}"
    if seg[0] == "skills" and len(seg) == 2 and h1.endswith(" jobs"): return f"skills={q(h1[:-5])}"
    if seg[0] == "roles" and len(seg) == 2 and h1.endswith(" jobs"): return f"q={q(h1[:-5])}"
    if seg[0] == "perks" and len(seg) == 2: return next((f"perk={q(nm)}" for nm, sl, _ in PERKS if sl == seg[1]), "")
    return {"contract": "etype=Contract", "part-time": "etype=Part-time", "internships": "etype=Internship"}.get(seg[0], "") if len(seg) == 1 else ""


# How many pages a topic list may have. It was first set to fit GitHub Pages' 1 GB (measured on 13 Nov 2026 with 41,187 open jobs,
# pages 3 to 5 of all lists weighed 63 MiB and page 2 another 66 MiB). The site has since moved to our own server and that limit and
# the workflow's size check are gone (15 Nov 2026); main() keeps one page a list by the owner's choice of 14 Nov (the search shows the
# rest). HRN_PAGE_CAP overrides it.
LIST_PAGES = 2


def act_row(href, label, more=(), note="", clip=""):
    """A page's main action right under its opening paragraph, so it is on the first phone screen (SEO_MAP.md): one ink button,
    then at most a couple of plain links and one short line. An href starting with "#" stays on the page.
    `clip`: the id of a text on the page (a letter, a template): the button then copies it (site.js, data-clip) and `href` is not used."""
    u = lambda h: h if h.startswith(("#", "http")) else f"{P}/{h}"
    btn = (f'<button class="btn primary sm" type="button" data-clip="{clip}" data-raw="1">{e(label)}</button>' if clip
           else f'<a class="btn primary sm" href="{u(href)}">{e(label)}</a>')
    return (f'<p class="lact">{btn}' + "".join(f'<a href="{u(h)}">{e(t)}</a>' for h, t in more)
            + (f"<span>{e(note)}</span>" if note else "") + "</p>")


def list_alert(h1, qs, jobs, compact=False):
    """The job alert of a list page, when an alert can ask for exactly what the list holds: its search filters are only words, a category,
    a place and "remote" (server/src/alerts.js). Search check, 18 Nov 2026: the first results for "<work> jobs" offer an alert beside
    the list; here only category and country pages had one."""
    if not qs or len(jobs) < 5: return ""
    f = dict(kv.split("=", 1) for kv in qs.split("&") if "=" in kv)
    # "sal" (least yearly pay) is an alert filter as well, and "age" needs none: an alert only ever sends jobs new since the last
    # letter (20 Nov 2026: /new/ and the /salary/ pages had no alert)
    f.pop("age", None)
    if set(f) - {"cat", "loc", "remote", "q", "skills", "sal"} or ("q" in f and "skills" in f):
        if not compact: return ""
        # the one-line alert above a list (26 Nov 2026): a filter the alert server does not know (entry-level, a type of work) is left out,
        # and the line says what it will send: "Email me new jobs in Dublin" over the entry-level jobs in Dublin
        cat_, loc_, rem_ = f.get("cat", ""), f.get("loc", ""), f.get("remote") == "1"
        if cat_ not in CAT: cat_ = ""
        if loc_ not in PLACE_TITLE: loc_ = ""
        if not (cat_ or loc_ or rem_): return ""
        what_ = "new " + ("remote " if rem_ else "") + (rlow(CAT[cat_]) + " " if cat_ else "") + "jobs" + (f" in {PLACE_TITLE[loc_]}" if loc_ else "")
        return alert_form(what_, cat=cat_, loc=loc_, remote=rem_, compact=True, label=f"Email me {what_}")
    words = unquote(f.get("q") or f.get("skills") or "")
    # every word of an alert must be in the job's title, company or skills, so a long descriptive name of a role ("Sales leader and VP of sales") would catch nothing
    if len(words.split()) > 3 or " and " in f" {words.lower()} ": return ""
    what = rlow(h1) if "q" in f else h1 if "skills" in f else h1[0].lower() + h1[1:]
    return alert_form(what if what.startswith("new ") else "new " + what, cat=f.get("cat", ""), loc=f.get("loc", ""), q=words, remote=f.get("remote") == "1",
                      sal=int(f.get("sal") or 0), compact=compact, label="Email me new jobs from this list" if compact else "")


ALERT_BLOCK = re.compile(r'<form class="alertf" .*?</form>', re.S)


def alert_line(block, label="Email me new jobs from this list"):
    """The one-line alert made from a full alert block a page passed (same filters, same words): lists show it right above their jobs."""
    hid = {k_: html.unescape(v_) for k_, v_ in re.findall(r'<input type="hidden" name="(\w+)" value="([^"]*)">', block)}
    m_ = re.search(r'data-what="([^"]*)"', block)
    what = html.unescape(m_.group(1)) if m_ else "new jobs"
    return alert_form(what, cat=hid.get("cat", ""), loc=hid.get("loc", ""), q=hid.get("q", ""), remote=hid.get("remote") == "1",
                      sal=int(hid.get("sal") or 0) if (hid.get("sal") or "").isdigit() else 0, compact=True, label=label)


def list_line(jobs, what="open"):
    """The one line under a list's heading: how many are open, how many are new this week, when they were checked."""
    k_ = sum(1 for j in jobs if j.get("active", True))
    if not k_: return f"<b>{len(jobs):,}</b> closed jobs, kept for reference"
    week_ = HUB["week"] or (datetime.date.today() - datetime.timedelta(days=7)).isoformat()
    new_ = sum(1 for j in jobs if j.get("active", True) and (j["posted"] or "") >= week_)
    return (f"<b>{k_:,}</b> {what} · {new_:,} new this week · checked {fdate(TODAY, False)} · "
            f'<a href="{P}/methodology/">How we check</a>')


def list_narrow(qs, jobs):
    """A row of ways to narrow a list, each with the number of its jobs that pass: the list's own search with one more filter.
    (Search check, 18 Nov 2026: every first result for a "<work> jobs" query has filters over its list; these pages had a button
    that kept the list and no way to narrow it without opening the search.) A filter the list already has, or that leaves fewer
    than three jobs or all of them, is not shown."""
    if not qs or len(jobs) < 20: return ""
    week = HUB["week"] or (datetime.date.today() - datetime.timedelta(days=7)).isoformat()
    opts = [("remote=1", "Remote", sum(1 for j in jobs if j["remote"])), ("entry=1", "Entry-level", sum(1 for j in jobs if j.get("entry"))),
            ("salary=1", "Pay stated", sum(1 for j in jobs if j.get("salary"))), ("age=7", "Posted this week", sum(1 for j in jobs if (j["posted"] or "") >= week))]
    have = {kv.split("=")[0] for kv in qs.split("&")}
    items = [f'<a href="{P}/jobs/?{e(qs)}&amp;{kv}">{lab}<i>{k:,}</i></a>' for kv, lab, k in opts if kv.split("=")[0] not in have and 3 <= k < len(jobs)]
    return ('<div class="pillrow lnarrow" role="navigation" aria-label="Narrow this list"><b>Narrow this list</b>' + "".join(items) + "</div>") if len(items) >= 2 else ""


def list_save(h1, qs, feed_path="", links=()):
    """A list page's main action on the first phone screen: keep the list. It goes into My jobs as the search that gives the same
    jobs, and My jobs counts the jobs posted since the last look (site.js; nothing is sent anywhere). The list's RSS feed beside it,
    then `links`: [(path, text)], a couple of plain links that belong next to the action."""
    lk = "".join(f'<a href="{P}/{u}">{e(t)}</a>' for u, t in links)
    if not qs: return f'<p class="lact">{lk}</p>' if lk else ""       # a list no search reproduces cannot be kept: no button, as before
    rss = (f'<a href="{P}/{feed_path}feed.xml">RSS feed</a>' if feed_path else "") + lk
    return (f'<p class="lact"><button class="btn primary sm" type="button" data-save-list="{e(qs)}" data-label="{e(h1)}">Save this list</button>{rss}'
            '<span>My jobs then shows how many are new each time you come back. No account, no email.</span></p>')


def alert_form(what, cat="", loc="", search=False, q="", remote=False, sal=0, compact=False, label=""):
    """"Email me new jobs like these": the free job alert sign-up (server/src/alerts.js), small and reusable. Shown only once the API is
    on (config.json api_url): a form that goes nowhere is not shown (rule 7). Without a script the form posts itself and the API answers
    with a page; with one, site.js sends it and writes the answer under it. On the search page (search=True) site.js copies the current
    search (words, category, place, remote, least pay) into the hidden fields when it is sent. The field "website" is for programs only."""
    if not CFG["api_url"]: return ""
    uid = "alert-" + re.sub(r"[^a-z0-9-]+", "-", (q or cat or loc or (f"pay-{sal}" if sal else "") or ("remote" if remote else "") or "search").lower()).strip("-")
    hid = "".join(f'<input type="hidden" name="{k}" value="{e(v)}">' for k, v in (("cat", cat), ("loc", loc), ("q", q), ("remote", "1" if remote else ""), ("sal", str(sal) if sal else "")) if v)
    if search: hid = "".join(f'<input type="hidden" name="{k}" value="">' for k in ("q", "cat", "loc", "remote", "sal"))
    if compact:
        # One line (26 Nov 2026): the same alert where people decide, above the jobs of a list or beside Apply: a field and one press,
        # weekly unless they pick daily. The same fields, server and script as the block below; how the address is kept is linked in the line.
        lab_ = label or f"Email me {what}"
        return (f'<form class="alertf alert1" method="post" action="{e(CFG["api_url"])}/api/alerts" data-alert{" data-alert-search" if search else ""} data-what="{e(what)}" aria-label="{e(lab_)}">'
                f'<label class="alert1-l" for="{uid}-e">{e(lab_)}</label><span class="alert1-f"><input id="{uid}-e" type="email" name="email" required autocomplete="email" maxlength="254" placeholder="Your email">'
                f'<select name="freq" aria-label="How often"><option value="weekly">Weekly</option><option value="daily">Daily</option></select>'
                '<button class="btn ghost" type="submit">Email me</button></span>'
                '<p class="alertf-hp" aria-hidden="true"><label>Leave this empty <input type="text" name="website" tabindex="-1" autocomplete="off"></label></p>'
                f'{hid}<span class="note alert1-n">Free, stop any time. <a href="{P}/privacy/#alerts">Your address</a></span><p class="note" role="status" aria-live="polite" data-alert-out></p></form>')
    return (f'<form class="alertf" method="post" action="{e(CFG["api_url"])}/api/alerts" data-alert{" data-alert-search" if search else ""} data-what="{e(what)}" aria-labelledby="{uid}-h">'
            f'<p class="sec-label">Alerts</p><h2 class="tw" id="{uid}-h">Free job alerts: <b>{e(what)}</b></h2>'
            '<p>New jobs by email, once a day or once a week, at most 20 in a letter. We send a link to confirm first, and every letter can be stopped in one click.</p>'
            f'<div class="alertf-row"><label for="{uid}-e">Your email</label><input id="{uid}-e" type="email" name="email" required autocomplete="email" maxlength="254">'
            f'<label for="{uid}-f">How often</label><select id="{uid}-f" name="freq"><option value="daily">Daily</option><option value="weekly">Weekly</option></select>'
            '<button class="btn primary" type="submit">Email me new jobs</button></div>'
            '<p class="alertf-hp" aria-hidden="true"><label>Leave this empty <input type="text" name="website" tabindex="-1" autocomplete="off"></label></p>'
            f'{hid}<p class="note" role="status" aria-live="polite" data-alert-out></p>'
            f'<p class="note">We keep your address and this search until you unsubscribe, and a note of each letter for 30 days. <a href="{P}/privacy/#alerts">How alerts handle your address</a></p></form>')


def plural_role(noun):
    """The plural of a job title for a title or a sentence: "Android developer" -> "Android developers", "secretary" -> "secretaries",
    "coach" -> "coaches", "chief of staff" -> "chiefs of staff". Only the head noun changes."""
    m_ = re.match(r"^(.*?)(\b\w+)((?: (?:of|for|in|to) .+?)?(?: \([^)]*\))?)$", noun.strip())     # "registered nurse (RN)" -> "registered nurses (RN)"
    head_, w_, tail_ = (m_.group(1), m_.group(2), m_.group(3) or "") if m_ else ("", noun, "")
    lw_ = w_.lower()
    if lw_ in ("staff", "personnel", "crew", "police", "people"): pw_ = w_
    elif lw_.endswith("person"): pw_ = w_[:-6] + ("People" if w_[-6].isupper() else "people")
    elif lw_.endswith("man") and lw_ not in ("human", "german"): pw_ = w_[:-3] + w_[-3:].replace("man", "men")
    elif re.search(r"[^aeiou]y$", lw_): pw_ = w_[:-1] + "ies"
    elif re.search(r"(s|sh|ch|x|z)$", lw_): pw_ = w_ + "es"
    else: pw_ = w_ + "s"
    return head_ + pw_ + tail_


def tidy_list_desc(desc, jobs):
    """The meta description of a list page, as Google shows it under the title (24 Nov 2026). Search Console: the location pages stand at
    positions 5 to 9 for "entry level jobs", "virtual assistant jobs", "work from home jobs" and "marketing jobs" (searchers in Dublin,
    Lithuania, Bulgaria, France) with no clicks, and their line read "83 open roles: Entry-level jobs in Dublin at companies. Updated
    hourly. Collected from … updated every hour": a placeholder left unfilled and the same promise twice. Now the companies are named
    and the line leads with what was searched: "Entry-level jobs in Dublin: 83 open now at Designer Group, Stripe and Google." The
    closing sentence about the hourly check is added once, by fit_desc."""
    if " at companies" in desc and jobs:
        top = [c for c, _ in Counter(j.get("company", "") for j in jobs if j.get("company")).most_common(3)]
        if top:
            desc = desc.replace(" at companies", " at " + (top[0] if len(top) == 1 else ", ".join(top[:-1]) + " and " + top[-1]), 1)
    m_ = re.match(r"^([\d,]+) open roles?: (.+?) at (.+?)\.(.*)$", desc)
    if m_:
        desc = f"{m_.group(2)}: {m_.group(1)} open now at {m_.group(3)}.{m_.group(4)}"
    desc = re.sub(r"\s*Updated hourly\.", "", desc).replace(", updated hourly.", ".").strip()
    return desc[:1].upper() + desc[1:]          # "part-time jobs: 587 open now" began in lower case (24 Nov 2026)


