# Records that are not job openings, or not from an employer (teardown, 26 Nov 2026). A recruiter's cold email posted as a job ("TiffanyKnaul",
# $650K-$900K, first in the home page's "Highest paid") and a recruiter's own list of candidates ("Elyse Murphy Candidates", "Scott Wilson's
# Candidates") were shown as jobs with "✓ Employer's own posting"; a hiring system's folder stood in for the employer's name.
PLACEHOLDER_CO = re.compile(r"(?i)\bdo not use\b|^default\b|\bdefault(?: page)?$|^test$|^select where to post\b|^all jobs?\b|^all job postings$|\bdefault career page\b")
CANDIDATE_LIST = (re.compile(r"(?i)^[\w.-]+(?: [\w.-]+)?\s*['’]s candidates?$"),        # "Michelle’s candidates", "Scott Wilson's Candidates"
                  re.compile(r"^[A-Z][a-z]+ [A-Z][a-z]+ [Cc]andidates$"))               # "Elyse Murphy Candidates"
COLD_EMAIL = (re.compile(r"(?i)\b(?:profile|background)\b[^.?!]{0,30}\bsimilar to yours\b"),
              re.compile(r"(?i)\bwould you have (?:some )?time for a (?:brief|quick|short) (?:call|chat|conversation)\b"),
              re.compile(r"(?i)\b(?:came across|reviewed|was impressed by) your (?:profile|resume|background|linkedin)\b"),
              re.compile(r"(?i)\bthought it would make sense to (?:connect|reach out|introduce myself)\b"))
COPY_OF = re.compile(r"(?i)^\s*(?:copy of\s+)+")         # "Copy of Copy of Analyst KYC" too (live, 26 Nov 2026)
# A hiring system's test or example posting (Search Console, 27 Nov 2026: /job/example-of-pdf-resume-linkedin/ was crawled and not indexed;
# "LinkedIn" there is a JazzHR sandbox whose 14 postings were test jobs, "Ferret Dentist" and "Test job with correct answer" among them).
# The titles are the open ones of that day: "Test", "Sample Job", "Template Job", "Demo Job", "Test Req - Do Not Apply", "DUMMY TEST JOB -
# DO NOT POST", ": For testing purposes only (DO NOT APPLY)", "DO NOT USE Generic Faculty and Administrative Application", "TEMPLATE - Hair
# Stylist / Colorist", "Digital Designer (Test Job)". The word alone is not enough: "Sample Coordinator", "Demo Technician", "Template
# Specialist", "Test Engineer", "Testing Coordinator" and "Test & Evaluation Engineer" are jobs, and "(Apply directly to Skyview Academy - DO
# NOT apply online with DCSD)" is a job to apply for elsewhere.
TEST_TITLE = re.compile(r"(?i)^\W*(?:test(?:ing)?|dummy|fake|template|placeholder)\W*$"
                        r"|^\W*(?:test|sample|example|demo|dummy|fake|template|placeholder)\s+(?:job|post(?:ing)?|position|requisition|req|role|opening|listing|vacancy)s?\b"
                        r"|\b(?:test|dummy|sample|template) job\b"
                        r"|^\W*(?:test|template)(?:\s+[-–]\s|\s*[:|]\s)"
                        r"|^\W*(?:an? )?(?:example|sample) of\b"
                        r"|\bdo not (?:use|post)\b|\bfor testing (?:purposes|only)\b|\btesting purposes\b|\btest(?:ing)? only\b|\bplease ignore\b|\bplaceholder\b"
                        r"|\btest\b.*\bdo not apply\b")
SANDBOX_MIN = 3         # a board with at least this many test postings, a third or more of its open ones, is a hiring system's sandbox
# Boards named as a hiring system's sandbox or staging copy (sources*.json on 27 Nov 2026): Gem's demo boards ("Y Combinator [Sandbox]",
# "Webflow ATS Sandbox", "Cartwheel [Sandbox]", each with the same six jobs: CFO, Data Scientist ... Software Engineering Intern), "PROSE -
# Sandbox", "myInterview - Staging" ("Testing close and re-open jobs"), "NCC 2024 - Test 1" ("testjob42"), "ats_sandbox_yello.co", and Gem's
# own test company "Oats Testing" (106 open: "Adam Oats Test Job (Copy) (Copy)", "Brad bug bash perms"). Not "Sandbox Mutual Insurance",
# "SandboxAQ", "Learning Sandbox", "The Sandbox" or a testing laboratory ("Atlantic Testing Laboratories", "Inspired Testing").
SANDBOX_CO = re.compile(r"(?i)[\[(]\s*sandbox\s*[\])]|\bats sandbox$|hr sandbox$|^(?:[a-z]+_)*sandbox_|\s[-–]\s*(?:sandbox|staging)$|\s[-–]\s*test \d+$|^oats testing$")
# A title the hiring system did not give ("Unavailable": 135 open iCIMS jobs on 27 Nov 2026, 120 of them at S&B Engineers and Constructors);
# iCIMS writes the real one in the posting's address (/jobs/14717/project-expeditor/job), which is read instead. The record's slug stays.
LOST_TITLE = re.compile(r"(?i)^\W*(?:unavailable|untitled|no title|n/?a|null|none)\W*$")
ICIMS_TITLE = re.compile(r"\.icims\.com/jobs/\d+/([a-z0-9]+(?:-[a-z0-9]+)*)/job\b")
SMALL_WORDS = {"and", "or", "of", "the", "a", "an", "in", "on", "at", "for", "to", "with", "by", "per"}
UPPER_WORDS = {"ii", "iii", "iv", "vi", "vii", "viii", "rn", "lpn", "lvn", "cna", "hvac", "it", "hr", "qa", "ai", "ui", "ux", "md", "np", "pa",
               "cdl", "ceo", "cfo", "cto", "vp", "usa", "uk", "ems", "emt", "er", "icu", "pt", "ot", "slp", "bcba", "rbt", "ma", "erp", "crm", "seo"}


def lost_title(j):
    """The title in an iCIMS posting's address, for a record whose title the hiring system did not give ("Unavailable"), else ""."""
    if not LOST_TITLE.match(j.get("title") or ""): return ""
    m = ICIMS_TITLE.search(j.get("url") or "")
    if not m: return ""
    ws = m.group(1).split("-")
    words = [w.upper() if w in UPPER_WORDS else w if (w in SMALL_WORDS and i) else w.capitalize() for i, w in enumerate(ws)]
    return " ".join(words) if len(" ".join(words)) >= 3 else ""


assert lost_title({"title": "Unavailable", "url": "https://careers-sbec.icims.com/jobs/14717/project-expeditor/job"}) == "Project Expeditor"
assert lost_title({"title": "Unavailable", "url": "https://careers-ameritfleet.icims.com/jobs/24071/generator-technician-d/job"}) == "Generator Technician D"
assert lost_title({"title": "Unavailable", "url": "https://careers-x.icims.com/jobs/1/senior-claim-examiner-ii/job?hub=7"}) == "Senior Claim Examiner II"
assert lost_title({"title": "Project Expeditor", "url": "https://careers-sbec.icims.com/jobs/14717/project-expeditor/job"}) == lost_title({"title": "Unavailable", "url": "https://x.com/1"}) == ""


def sandbox(titles):
    """True when the titles of a board's open postings are mostly a hiring system's test postings (TEST_TITLE): SANDBOX_MIN or more of them,
    a third or more of the board. Every posting of such a board is a test, even one with a plausible title ("Ferret Dentist", "Assistant
    Chef" on the JazzHR sandbox named "LinkedIn"). live.py asks it of each board it reads."""
    titles = list(titles)
    k = sum(1 for t in titles if TEST_TITLE.search(t or ""))
    return k >= SANDBOX_MIN and 3 * k >= len(titles)


def junk_reason(j):
    """Why a record is not a job to list (one of SIFTED's keys), or "" for a job. A cold email needs two of COLD_EMAIL's phrases: one alone
    can be an ordinary sentence. live.py asks the same of every job it finds, so a record left out here never comes back from the server."""
    co = j.get("company") or ""
    if PLACEHOLDER_CO.search(co) and co not in CO_RENAME: return "placeholder"
    t = (j.get("title") or "").strip()
    if any(rx.search(t) for rx in CANDIDATE_LIST): return "candidates"
    if TEST_TITLE.search(t): return "test_posting"
    if SANDBOX_CO.search(co): return "sandbox"
    text = (j.get("excerpt") or "") + " " + (j.get("desc") or "")
    # the first phrase alone is enough (a recruiter speaking about the reader's profile): the record keeps only the opening lines of
    # most postings, and "TiffanyKnaul" kept only that one (live, 26 Nov 2026); the others need a second
    hits_ = [i for i, rx in enumerate(COLD_EMAIL) if rx.search(text)]
    if 0 in hits_ or len(hits_) >= 2: return "cold_email"
    return ""


SIFTED = Counter()        # what sift() left out in this build, by reason; FACTS and the methodology page say it
MENDED = Counter()        # what sift() kept but mended: "Copy of" taken off a title, a title read from the posting's address
# The address of a copy sift() leaves out -> the address of the posting it copies (Search Console, 27 Nov 2026: /job/custodian-part-time-
# z-do-not-use/ answered 404 once the "Z. Do Not Use" board's copy of Paylocity posting 3628332 left the lists; the posting is
# /job/custodian-part-time-catholic-schools/). records.save() stores it in data/jobs.db, and the page server answers such an address with a
# 301 to the posting (records.Store.moved), as it does for a job published live under one address and given another by the hourly record.
MOVED_JOB = {}
# A company whose every record sift() leaves out -> its name (27 Nov 2026: the JazzHR sandbox "LinkedIn" and Gem's "Oats Testing" lost
# their pages with their test postings). Its address never answers 404: write_gone_companies() keeps a page of the H-1B filings we hold
# for the name (/companies/linkedin/: LinkedIn Corporation's filings), or hands the address over to /companies/. check.py tests it from
# data/companies_gone.json.
GONE_CO = {}


def sift(jobs):
    """The records the site lists, before anything else reads them. Leaves out what junk_reason() names, the copies of a placeholder board
    that repeats an employer's own board (the same posting id on both: Paylocity's "ALL JOB POSTINGS" held 47 of Louisiana Cat's 48 jobs),
    and an ATS copy ("Copy of Graphic Designer") of a job the employer also lists under its real title; other "Copy of" titles lose the words.
    Every posting of a hiring system's sandbox goes too (sandbox()), and a title the system did not give takes the one in its address
    (lost_title)."""
    own = {}                  # (hiring system, posting id) -> (slug, open) of that posting on the employer's own board, an open one first
    open_titles = defaultdict(list)
    for j in jobs:
        co = j.get("company") or ""
        if not PLACEHOLDER_CO.search(co):
            ats = j["id"].split("-", 1)[0]
            k_ = (ats, j["id"][len(ats) + len(slugify(co)) + 2:])
            if k_ not in own or (j.get("active") and not own[k_][1]): own[k_] = (j["slug"], bool(j.get("active")))
        if j.get("active"): open_titles[co].append(j.get("title") or "")
    boxes = {co for co, ts in open_titles.items() if sandbox(ts)}
    if boxes: print("hiring systems' sandboxes left out: " + ", ".join(f"{co} ({len(open_titles[co])} open)" for co in sorted(boxes)))
    keys = {}                 # (company, title, place) -> (slug, open) of a job under its real title, an open one first
    for j in jobs:
        if not COPY_OF.match(j.get("title") or ""):
            k_ = (j.get("company"), (j.get("title") or "").strip().lower(), (j.get("location") or "").strip().lower())
            if k_ not in keys or (j.get("active") and not keys[k_][1]): keys[k_] = (j["slug"], bool(j.get("active")))
    MOVED_JOB.clear()
    GONE_CO.clear()
    out = []
    for j in jobs:
        co = j.get("company") or ""
        if co in boxes:
            SIFTED["sandbox"] += 1; continue
        if (t_ := lost_title(j)):
            j["title"] = t_
            MENDED["title_from_address"] += 1
        if PLACEHOLDER_CO.search(co):
            ats = j["id"].split("-", 1)[0]
            if (got_ := own.get((ats, j["id"][len(ats) + len(slugify(co)) + 2:]))):
                if got_[0] != j["slug"]: MOVED_JOB[j["slug"]] = got_[0]
                SIFTED["placeholder_copy"] += 1; continue
        why = junk_reason(j)
        if why:
            SIFTED[why] += 1; continue
        if COPY_OF.match(j.get("title") or ""):
            plain = COPY_OF.sub("", j["title"]).strip()
            if (got_ := keys.get((co, plain.lower(), (j.get("location") or "").strip().lower()))):
                if got_[0] != j["slug"]: MOVED_JOB[j["slug"]] = got_[0]
                SIFTED["copy"] += 1; continue
            j["title"] = plain
            MENDED["copy_renamed"] += 1
        out.append(j)
    kept_ = {j["slug"] for j in out}
    for old_ in [o_ for o_, n_ in MOVED_JOB.items() if o_ in kept_ or n_ not in kept_]: del MOVED_JOB[old_]     # never over a page that stays
    # companies left with no record (a renamed placeholder board hands over to its new name instead: write_renamed_companies)
    stay_ = {slugify(CO_RENAME.get(j.get("company") or "", j.get("company") or "")) for j in out} | {slugify(c_) for c_ in CO_RENAME}
    for j in jobs:
        co_ = j.get("company") or ""
        if co_ and slugify(co_) and slugify(co_) not in stay_: GONE_CO.setdefault(slugify(co_), co_)
    return out


def _sift_test():
    """sift() on made-up records: the placeholder board's copy and the "Copy of" copy hand their addresses over to the posting they copy."""
    keep_ = (Counter(SIFTED), Counter(MENDED))
    js_ = [{"id": "paylocity-catholic-schools-3628332", "company": "Catholic Schools", "title": "Custodian Part Time", "location": "Melbourne, FL", "slug": "custodian-part-time-catholic-schools", "active": True},
           {"id": "paylocity-z-do-not-use-3628332", "company": "Z. Do Not Use", "title": "Custodian Part Time", "location": "Melbourne, FL", "slug": "custodian-part-time-z-do-not-use", "active": True},
           {"id": "paylocity-z-do-not-use-4205546", "company": "Z. Do Not Use", "title": "Accounting Billing Coordinator", "location": "Orlando, FL", "slug": "accounting-billing-coordinator-z-do-not-use", "active": True},
           {"id": "lever-acme-1", "company": "Acme", "title": "Graphic Designer", "location": "Austin, TX", "slug": "graphic-designer-acme", "active": False},
           {"id": "lever-acme-2", "company": "Acme", "title": "Copy of Graphic Designer", "location": "Austin, TX", "slug": "copy-of-graphic-designer-acme", "active": True},
           {"id": "icims-s-b-1", "company": "S&B", "title": "Unavailable", "url": "https://careers-sbec.icims.com/jobs/14717/project-expeditor/job", "location": "", "slug": "unavailable-s-b", "active": True}]
    out_ = sift(js_)
    assert [j["slug"] for j in out_] == ["custodian-part-time-catholic-schools", "accounting-billing-coordinator-z-do-not-use", "graphic-designer-acme", "unavailable-s-b"], [j["slug"] for j in out_]
    assert MOVED_JOB == {"custodian-part-time-z-do-not-use": "custodian-part-time-catholic-schools", "copy-of-graphic-designer-acme": "graphic-designer-acme"}, MOVED_JOB
    assert out_[-1]["title"] == "Project Expeditor" and out_[-1]["slug"] == "unavailable-s-b"
    assert GONE_CO == {}, GONE_CO          # the copies' boards keep their pages ("Z. Do Not Use" through its new name)
    with contextlib.redirect_stdout(io.StringIO()): sift(js_ + [{"id": "jazzhr-linkedin-1", "company": "LinkedIn", "title": "Example of pdf resume", "location": "", "slug": "example-of-pdf-resume-linkedin", "active": True},
                {"id": "jazzhr-linkedin-2", "company": "LinkedIn", "title": "Test Job", "location": "", "slug": "test-job-linkedin", "active": True},
                {"id": "jazzhr-linkedin-3", "company": "LinkedIn", "title": "Test job for EEOC", "location": "", "slug": "test-job-for-eeoc-linkedin", "active": True},
                {"id": "jazzhr-linkedin-4", "company": "LinkedIn", "title": "Ferret Dentist", "location": "", "slug": "ferret-dentist-linkedin", "active": True},
                {"id": "gem-oats-testing-1", "company": "Oats Testing", "title": "Brad bug bash perms", "location": "", "slug": "brad-bug-bash-perms-oats-testing", "active": True}])
    assert GONE_CO == {"linkedin": "LinkedIn", "oats-testing": "Oats Testing"}, GONE_CO
    SIFTED.clear(); SIFTED.update(keep_[0]); MENDED.clear(); MENDED.update(keep_[1]); MOVED_JOB.clear(); GONE_CO.clear()


_sift_test()


