LEVEL_ENTRY = re.compile(r"(?i)\bentry[- ]level\b")
LEVEL_STAFF = re.compile(r"(?i)\bstaff (?:physician|nurse|pharmacist|psychiatrist|psychologist|therapist|chaplain|dentist|veterinarian|member|support|rn)s?\b|\b(?:teaching|support|nursing|medical|kitchen|office|clinical|program|direct care|wait|event|seasonal|part[- ]time) staff\b")
LEVEL_LEAD = re.compile(r"(?i)\b(?:lead|director|head of|chief|principal|vp|vice president|supervisor|manager)\b")
for _t, _lv in (("Entry Level Marketing Lead", "Junior"), ("Staff Physician, Internal Medicine", ""), ("Part-Time Teaching Staff", ""), ("Staff Software Engineer", "Lead"), ("Lead Teacher", "Lead")):
    _l = collect.level(_t)
    if _l == "Lead" and LEVEL_ENTRY.search(_t): _l = "Junior"
    elif _l == "Lead" and LEVEL_STAFF.search(_t) and not LEVEL_LEAD.search(_t): _l = ""
    assert _l == _lv, (_t, _l)
FOR_JUNIORS = re.compile(r"(?i)\b(?:early[- ]career|university|campus|graduate|new grad|intern(?:ship)?)s?\b[^,]*?\b(?:recruit\w*|sourcer|program manager|programs? lead|coordinator|talent partner)\b")
REQ_CODE = [re.compile(r"\s*[\(\[]\s*(?:R|JR|REQ|Req|req|ID|Job ID|Requisition(?: ID)?)\s*[-#:_ ]?\s*\d{3,}\s*[\)\]]"),   # "(R6043)", "[REQ-12345]"
            re.compile(r"\s*[\(\[]\s*\d{5,}\s*[\)\]]"),                                                    # "(123456)", never a year
            re.compile(r"\s*[,–-]?\s*#\d{3,}\s*$"),                                                         # ", #1463"
            re.compile(r"\s*[-–]\s*(?:R|JR|REQ)[-_]?\d{4,}\s*$")]                                         # " - R12345"


def tidy_job_title(t):
    """A job title as a reader wants it (24 Nov 2026). Google's job posting guidelines ask for no codes in the title, and 1.7% of a
    3,000-page sample carried one ("Staff Engineer, Electromechanical (R6043)", "Process Lead, Philadelphia, #1463"). A "|" between
    parts ("… Grafana Frontend | Canada | Remote") also read as the end of the title, so the page title lost the company."""
    t2 = t
    for rx in REQ_CODE: t2 = rx.sub("", t2)
    t2 = re.sub(r"\s*\|\s*", ", ", t2).strip(" ,-–")
    t2 = re.sub(r"(?<=[A-Za-z])- (?=\w)", " - ", t2)            # "Provider Sales- West": a dash glued to the word before it
    return t2 if len(t2) >= 3 else t


LAPS, LAP_NOW = [], [time.time(), "start: reading the record"]
def lap(name):
    """Build timing: ends the stage that was running and starts the next one. The slowest stages are printed when the build ends,
    so every run on the full record says where its minutes went (the local record is a fifth of it)."""
    now = time.time()
    LAPS.append((now - LAP_NOW[0], LAP_NOW[1])); LAP_NOW[0], LAP_NOW[1] = now, name


DOUBLE_ESC = re.compile(r"&amp;(amp|lt|gt|quot|apos|nbsp|#\d{2,5}|#x[0-9a-fA-F]{2,4});")

ENTITY_TEXT = re.compile(r"&(?:amp|lt|gt|quot|apos|nbsp|#\d{2,5}|#x[0-9a-fA-F]{2,4});")


def main():
    LAP_NOW[0] = time.time()
    CUT_ON[0] = True                  # pages of this build link css/<kind>.css, written by cut_files() at the end
    if OUT.exists(): shutil.rmtree(OUT)
    OUT.mkdir()
    db = jobsdb.load(ROOT / "data" / "jobs.json")   # one record at a time, see jobsdb.py
    jobs = list(db.values())
    for j_ in jobs:                              # a feed that escaped its text twice ("Health &amp;amp; Safety") showed a literal "&amp;" on the page
        if "&amp;" in (j_.get("desc") or ""): j_["desc"] = DOUBLE_ESC.sub(r"&\1;", j_["desc"])
        if ENTITY_TEXT.search(j_.get("excerpt") or ""): j_["excerpt"] = html.unescape(j_["excerpt"])      # plain text: an entity in it is the same slip
    jobs = sift(jobs)                            # cold emails, candidate lists, placeholder boards, test postings, sandboxes and ATS copies (sift, junk_reason)
    print("left out as not jobs or not employers: " + (", ".join(f"{k} {v:,}" for k, v in SIFTED.most_common()) or "none")
          + "; mended: " + (", ".join(f"{k} {v:,}" for k, v in MENDED.most_common()) or "none")
          + f"; {len(MOVED_JOB):,} addresses of copies left out hand over (301) to the posting they copy")
    for j_ in jobs:                              # Workday entity codes read as names (CO_RENAME); the old address hands over below
        j_["company"] = CO_RENAME.get(j_.get("company"), j_.get("company"))
    paid_file = ROOT / "paid.json"  # employer-submitted listings, kept in the main branch
    for p in (json.loads(paid_file.read_text()) if paid_file.exists() else []):
        base = f"{slugify(p['title'])}-{slugify(p['company'])}"
        jobs.append({"id": "paid-" + base, "slug": base, "location": "", "remote": False, "dept": "", "excerpt": "", "level": "", "tags": [],
                     "russian": False, "salary": "", "posted": TODAY, "first_seen": TODAY, "cat": OTHER[0],
                     "active": p.get("expires", "9999") >= TODAY, **p})
    lap('paid placements bought in the account (written by collect.py')
    # paid placements bought in the account (written by collect.py from the API): promoted jobs and sponsors
    place_file = ROOT / "data" / "placements.json"
    PAID = json.loads(place_file.read_text()) if place_file.exists() else {}
    boost = defaultdict(dict)
    for b in PAID.get("boosts", []):
        if b.get("until", "") >= TODAY: boost[b.get("slug")][b.get("kind")] = b
    for j in jobs:
        # What the account sold for this job, each with its last day: a Standard boost ("featured"), a Premium boost (a turn in the top
        # of its lists, the cover picture), the "Urgently hiring" badge, and a bump, which sorts the job as if it was posted when the
        # bump was bought. A job posted in the account carries these itself; a job we read from a careers page gets them by its slug.
        bought = boost.get(j["slug"], {})
        till = lambda k_: max(j.get(k_ + "_until") or "", (bought.get(k_) or {}).get("until", ""))
        j["premium"] = bool(j["active"] and till("premium") >= TODAY)
        j["pinned"] = bool(j["premium"] or (j["active"] and till("pinned") >= TODAY))
        j["featured"] = bool(j["pinned"] or (j["active"] and till("featured") >= TODAY))
        j["urgent"] = bool(j["active"] and till("urgent") >= TODAY)
        j["bump"] = bump_stamp(j.get("bumped") or (bought.get("bump") or {}).get("at", "")) if j["active"] else 0
        j["cover"] = (j.get("cover") or (bought.get("premium") or {}).get("cover", "")) if j["premium"] else ""
        if j["location"].lower() in {"n/a", "na", "none", "tbd", "-", "null", "not specified"}: j["location"] = ""
        # "Remote- USA", "Dublin-Dublin, UNAVAILABLE, IE": a dash glued to the word before it and a hiring system's placeholder (24 Nov 2026)
        j["location"] = tidy_location(re.sub(r",\s*UNAVAILABLE\b", "", re.sub(r"(?<=[A-Za-z])- (?=\w)", " - ", j["location"])))
        j["title"] = tidy_job_title(calm_title(j["title"]))
        # "Associate RVP, Provider Sales" was a junior role in the lists and on its page (24 Nov 2026): collect.level() knows
        # "Associate VP" and "Associate Director" but not the regional and managing variants. Mended here, not in collect.py, whose
        # rules hash decides when every record is read again.
        j["cat"] = job_field(j["title"], j.get("cat"))         # behaviour analysts and technicians: Healthcare, not Data or Manufacturing (ABA_ROLE)
        if j["level"] == "Junior" and ASSOC_SENIOR.match(j["title"]): j["level"] = "Lead"
        elif j["level"] in ("Junior", "Intern") and FOR_JUNIORS.search(j["title"]): j["level"] = ""      # "Early Career & University Recruiter", "Intern Program Coordinator" hire juniors, are not ones
        # "Entry Level Marketing Lead" is entry level, and a staff physician or the teaching staff are no grade at all (data teardown, 26 Nov 2026:
        # collect.level() read "lead" and "staff" as Lead)
        elif j["level"] == "Lead" and LEVEL_ENTRY.search(j["title"]): j["level"] = "Junior"
        elif j["level"] == "Lead" and LEVEL_STAFF.search(j["title"]) and not LEVEL_LEAD.search(j["title"]): j["level"] = ""
        j["entry"] = j["level"] in ("Junior", "Intern")
        j["pool"] = bool(POOL_RX.search(j["title"]))
        j["salary"] = sane_pay(j["salary"])
        j["usd"] = usd_range(j["salary"])
        j["rkey"] = search_engine.role_key(j["title"], j["location"])      # one row per role in every list (collapse)
        j["usd_h"] = None if j["usd"] else usd_hourly(j["salary"])      # an hourly rate in US dollars: the search's pay filter reads it (search_engine.doc)
        # "Remote" from the hiring system, where the posting's own text asks for days in the office (collect.says_hybrid; records read before
        # 26 Nov 2026 were not checked, and only the last 14 days keep their text)
        if j["remote"] and j["active"] and (j.get("desc") or j.get("excerpt")) and collect.says_hybrid(TAG_RX.sub(" ", (j.get("desc") or "") + " " + (j.get("excerpt") or ""))):
            j["remote"], j["hybrid"] = False, True
        j["places"] = places_of(j["location"]) if j["active"] and j["location"] else []
        j["t"], j["ts"] = exact(j), stamp(j)
    active = [j for j in jobs if j["active"]]
    co_more(active)                              # "3 more open roles at Loris Gifts in Texas" on the job page's search line (job_desc)
    ALL_OPEN[0] = len(active)
    MIX_[0] = sum(1 for j in active if j["cat"] in ("engineering", "security", "product", "data-research", "design")) / max(len(active), 1)
    global LIST_PAGES
    LIST_PAGES = int(os.environ.get("HRN_PAGE_CAP") or 1)      # owner, 14 Nov: no Cloudflare yet, so the 70 MiB of second pages goes to more jobs; the search shows the rest
    archived = [j for j in jobs if not j["active"]]
    by_cat = defaultdict(list)
    for j in active: by_cat[j["cat"]].append(j)
    companies = defaultdict(list)
    for j in jobs: companies[j["company"]].append(j)
    n, m = len(active), len({j["company"] for j in active})
    NO_ANON = ("Employers can also post a job themselves; such a posting is published only after its link has been checked automatically, and it is labelled as posted by the employer"
               if CFG["api_url"] else "We do not accept anonymous postings")
    N_FEEDS = m     # employers read: every company with an open job (the old count of sources.json + sources_tech.json, 783, ignored all other boards)
    lap('How often a careers page is read: the boards in sources.json')
    # How often a careers page is read: the boards in sources.json and sources_tech.json every hour, those in sources_more.json in
    # turn (HRN_ROTATE in collect.py: every four hours). The copy says exactly that, never "every hour" for all of them.
    HOURLY_SET = {s_["name"] for f_ in ("sources.json", "sources_tech.json") if (ROOT / f_).exists() for s_ in json.loads((ROOT / f_).read_text())}
    ROT_SET = {s_["name"] for f_ in ("sources_more.json", "sources_ats.json") if (ROOT / f_).exists() for s_ in json.loads((ROOT / f_).read_text())}   # collect.ROTATING
    m_hourly = len({j["company"] for j in active if j["company"] in HOURLY_SET or j["company"] not in ROT_SET})
    lap('live.py on the server reads every board at least once an hou')
    # live.py on the server reads every board at least once an hour (config.json "live_collector"), so the four-hour rotation of the
    # hourly build no longer limits how often a company is checked
    ROTATING = m_hourly < len({j["company"] for j in active}) and not CFG.get("live_collector")
    remote = [j for j in active if j["remote"]]
    SALPCT = round(100 * sum(bool(j["salary"]) for j in active) / max(n, 1))
    WEEKNEW = sum(1 for j in active if (j["posted"] or "")[:10] >= (datetime.date.today() - datetime.timedelta(days=7)).isoformat())
    lap('What the site says about itself: one set of numbers (FACTS)')
    # What the site says about itself, counted once here and used on every page (teardown, 26 Nov 2026: the media kit said "783 employers
    # every hour and 5,827 every four hours", /methodology/ "25,194 company feeds every hour", /status/ "44% re-checked today", the home page
    # "14,137 new today" beside "188 posted today"). How often a board is read is a schedule (EVERY: the server reads boards in turn all
    # day and night); what was really re-checked is a measure (checked_24h: open jobs read again on the employer's list in the last 24
    # hours, from collect.py's checked_at, or a last_seen of today for a record written before checked_at existed). "New" and "posted
    # today" are the employer's own date, never the day we first read a job ("first read by us" is said as such where it is shown).
    ROTATING = False                    # the "N every hour, the rest every four hours" lines are gone: neither half was measured
    EVERY = "around the clock"
    def checked_t(j):
        try: return int(datetime.datetime.fromisoformat(str(j.get("checked_at") or "").replace("Z", "+00:00")).timestamp())
        except ValueError: return 0
    k24_ = sum(1 for j in active if checked_t(j) >= NOW - 86400 or j.get("last_seen") == TODAY)
    # Open more than 90 days, by the employer's own date (AI search teardown, 26 Nov 2026: "26% open 90+ days" counted the iCIMS stand-in
    # dates, two years before the day of reading, and the day we first read a job where a posting had no date). A posting without a date
    # of its own, or whose date is only the day it last changed (posted_from "lastmod", collect.icims_placeholder), says nothing of its
    # age: it is left out of the share and counted apart (dated_open + undated_open = open).
    d90_ = (datetime.date.today() - datetime.timedelta(days=LONG_OPEN)).isoformat()
    dated_ = [j for j in active if j.get("posted") and j.get("posted_from") != "lastmod"]
    o90_ = sum(1 for j in dated_ if j["posted"][:10] < d90_)
    FACTS.clear()
    FACTS.update(open=n, companies=m, checked_24h=k24_, checked_24h_pct=round(100 * k24_ / max(n, 1)),
                 posted_today=sum(1 for j in active if (j["posted"] or "")[:10] == TODAY), posted_7d=WEEKNEW,
                 first_read_today=sum(1 for j in active if j.get("first_seen") == TODAY), left_out=sum(SIFTED.values()),
                 usajobs=sum(1 for j in active if j["id"].startswith("usajobs-")), telegram=sum(1 for j in active if j.get("tg")),
                 dated_open=len(dated_), undated_open=n - len(dated_), open_90d=o90_, open_90d_pct=round(100 * o90_ / max(len(dated_), 1)))
    CHECK_LINE[0] = f"{FACTS['checked_24h_pct']}% of open jobs were re-checked on the employer’s own list in the last 24 hours"
    # where the jobs come from, said the same way everywhere (teardown: "only from employers' own pages" while USAJOBS and Telegram posts
    # were listed too); the counts are this build's
    SOURCE_LINE[0] = ("From employers’ own hiring systems" + (f"; {FACTS['usajobs']:,} US federal jobs from USAJOBS, the government’s own job site" if FACTS["usajobs"] else "")
                      + (f"; {FACTS['telegram']:,} posts from public Telegram job channels, marked as such and not checked with the employer" if FACTS["telegram"] else ""))
    print("facts: " + ", ".join(f"{k} {v:,}" for k, v in FACTS.items()))
    contact = " or ".join(x for x in [f'Telegram <a href="https://t.me/{e(CFG["contact_telegram"])}">@{e(CFG["contact_telegram"])}</a>' if CFG["contact_telegram"] else "",
                                      f'email <a href="mailto:{e(CFG["contact_email"])}">{e(CFG["contact_email"])}</a>' if CFG["contact_email"] else ""] if x)
    by_place_ = defaultdict(list)                     # one pass over the jobs instead of one per place (100 places x every job)
    for j in active:
        for s_ in set(j["places"]): by_place_[s_].append(j)
    places = [(name, slug, by_place_[slug]) for name, slug, rx in PLACES if len(by_place_.get(slug, ())) >= 5]
    OPEN.update(Counter(j["company"] for j in active))
    # the perks read here (BUILD_PERKS), from the full text or the opening lines. Each pattern needs one of its words (BUILD_PERK_KEYS),
    # so a plain test on the lower-cased text comes first: 7.8 s -> 1.7 s on the local sample, the same perks (24 Nov 2026)
    bp_rx = [(nm, re.compile(rx, re.I)) for nm, _, rx in BUILD_PERKS]
    for j in active:
        tx_ = (j.get("desc") or "") + " " + (j.get("excerpt") or "")
        low_ = tx_.lower()
        add_ = [nm for nm, rx in bp_rx if nm not in j.get("perks", []) and any(k_ in low_ for k_ in BUILD_PERK_KEYS[nm]) and rx.search(tx_)]
        if add_: j["perks"] = list(j.get("perks") or []) + add_
    PERK_OK.update(x for x, k in Counter(x for j in active for x in j.get("perks", [])).items() if k >= 8)
    wk = (datetime.date.today() - datetime.timedelta(days=7)).isoformat()
    wk14 = (datetime.date.today() - datetime.timedelta(days=14)).isoformat()
    for c, js in companies.items():
        opened = sum(1 for j in js if (j["posted"] or "") >= wk)
        closed_ = sum(1 for j in js if not j["active"] and (j.get("closed") or "") >= wk)
        net, base_ = opened - closed_, max(3, OPEN[c] // 10)
        PULSE[c] = (opened, closed_, "Ramping up" if net >= base_ else "Slowing down" if -net >= base_ else "Steady")
        # two weeks, not one: Bjakcareer closed its 1,548 jobs and put up 1,609 new ones in two batches a week apart
        op14_ = sum(1 for j in js if (j["posted"] or "") >= wk14) if opened >= CHURN_MIN else 0
        cl14_ = sum(1 for j in js if not j["active"] and (j.get("closed") or "") >= wk14) if op14_ else 0
        if min(op14_, cl14_) >= max(CHURN_MIN, OPEN[c] / 2): CHURN.add(c)
    print(f"boards that repost most of their jobs every week (CHURN): {len(CHURN):,}, {sum(OPEN[c] for c in CHURN):,} open jobs: " + ", ".join(sorted(CHURN, key=lambda c: -OPEN[c])[:10]))
    spans = defaultdict(list)
    for j in archived:
        try:
            d = (datetime.date.fromisoformat(j["closed"][:10]) - datetime.date.fromisoformat(j["posted"][:10])).days
        except Exception:
            continue
        if 0 <= d <= 400: spans[j["cat"]].append(d)
    for cs, ds in spans.items():
        if len(ds) >= 20: CLOSE_DAYS[cs] = int(median(ds))
    co_spans = defaultdict(list)
    for j in archived:
        try:
            d = (datetime.date.fromisoformat(j["closed"][:10]) - datetime.date.fromisoformat(j["posted"][:10])).days
        except Exception:
            continue
        if 0 <= d <= 400: co_spans[j["company"]].append(d)
    for c_, ds in co_spans.items():
        if len(ds) >= 5: CO_CLOSE[c_] = (len(ds), int(median(ds)))
    for cs in CAT:
        mids = [(lo + hi) / 2 for j in by_cat[cs] if j["usd"] for lo, hi in [j["usd"]]]
        if len(mids) >= 15: CATMED[cs] = median(mids)
        hm_ = [(h_[0] + h_[1]) / 2 for j in by_cat[cs] if (h_ := usd_hourly(j.get("salary")))]
        if len(hm_) >= 15 and cs != OTHER[0]: HMED[cs] = median(hm_)
        for lv in ("Intern", "Junior", "Senior", "Lead"):
            lm = [(lo + hi) / 2 for j in by_cat[cs] if j["level"] == lv and j["usd"] for lo, hi in [j["usd"]]]
            if len(lm) >= 15: EST[(cs, lv)] = median(lm)
    fam_medians(active)                          # the pay of the same work, for the jobs that state none (fam_estimate)
    top_cats = sorted((s for s in CAT if by_cat[s] and s != OTHER[0]), key=lambda s: -len(by_cat[s]))
    pop_sk = [t for t, _ in Counter(t for j in active for t in j["tags"]).most_common(10)]
    FOOT["pop"] = ('<p class="pop"><span>Popular searches:</span>' + "".join(f'<a href="{P}/skills/{TAG_SLUG.get(t, slugify(t))}/">{e(t)} jobs</a>' for t in pop_sk)
                   + "".join(f'<a href="{P}/locations/{slug}/">{pfl(slug)}Jobs in {e(name.removeprefix("the "))}</a>' for name, slug, _ in sorted(places, key=lambda x: -len(x[2]))[:6]) + "</p>")
    # The kinds of work by hours and by employer (moved here 21 Nov 2026 from their own sections below, which still build the pages): known
    # before the first page is written, so that the footer of every page links each list that exists. Until then /government-jobs/ had no
    # link from any other page but its own, /nonprofit-jobs/ and /job-posting-sites/ one, /temporary/ and /no-experience-jobs/ two.
    imm_jobs, noexp_jobs, fair_jobs = says_so(active, IMMEDIATE_RX), says_so(active, NO_EXPERIENCE_RX), says_so(active, FAIR_CHANCE_RX)
    noexp_jobs = [j for j in noexp_jobs if j["level"] not in ("Senior", "Lead") and (j.get("years") or 0) < 2]      # a senior title or "3+ years" is not "no experience"
    HOURS_NOT = {"weekend/": WEEKEND_NOT, "night-shift/": NIGHT_NOT}      # "no weekends", "no nights" are not weekend or night work (25 Nov 2026)
    HOURS = [(p_, h_, w_, js_) for p_, h_, rx_, w_ in (
        ("night-shift/", "Night shift jobs", r"night shift|overnight|3rd shift|third shift|graveyard|\bnights\b|2nd shift|second shift|swing shift|evening shift", "evening or night shifts"),
        ("weekend/", "Weekend jobs", r"weekend", "weekend work"),
        ("summer/", "Summer jobs and internships", r"\bsummer\b", "the summer months"),
        ("temporary/", "Temporary and seasonal jobs", r"seasonal|temporary|\btemp\b|fixed[- ]term", "a fixed term or a season"))
        if len(js_ := [j for j in active if re.search(rx_, HOURS_NOT.get(p_, NO_WORDS).sub(" ", j["title"] + " " + (j["excerpt"] or "")), re.I)]) >= 20]
    HOURS += [x for x in (("hiring-immediately/", "Jobs hiring immediately", "an immediate start", imm_jobs), ("no-experience-jobs/", "No experience jobs", "“no experience required”", noexp_jobs),
                                 ("fair-chance-jobs/", "Fair chance jobs", "a fair chance law or says it considers applicants with arrest or conviction records", fair_jobs)) if len(x[3]) >= 20]
    GOV_RX = re.compile(r"^(?:the )?(?:city|county|state|town|village|commonwealth|district|port|borough|township|parish) of\b|\b(?:county|city|state) government\b|"
                        r"\bdepartment of\b|\bpublic schools?\b|\bschool district\b|\bunified school\b|\b(?:transit|housing|port|water|airport) authority\b|\bcounty\s*$", re.I)
    SCHOOL_RX = re.compile(r"\bpublic schools?\b|\bschool district\b|\bunified school\b", re.I)
    gov_ = [j for j in active if j["id"].startswith("usajobs-") or GOV_RX.search(j["company"])]
    GOV_PAGE = len(gov_) >= 20
    np_file = json.loads((ROOT / "nonprofits.json").read_text()) if (ROOT / "nonprofits.json").exists() else {}
    np_cos = set(np_file.get("companies") or []) | {c for c in companies if NP_NAMES.search(c)} | {j["company"] for j in active if j.get("desc") and says_nonprofit(j["company"], j["desc"])}
    np_ = [j for j in active if j["company"] in np_cos]
    NP_PAGE = len(np_) >= 20
    TYPE_NAMES = {"night-shift/": "Night shift jobs", "weekend/": "Weekend jobs", "summer/": "Summer jobs", "temporary/": "Temporary jobs",
                  "hiring-immediately/": "Jobs hiring immediately", "no-experience-jobs/": "No experience jobs", "fair-chance-jobs/": "Fair chance jobs"}
    TYPE_LINKS = ([("part-time/", "Part-time jobs"), ("contract/", "Contract jobs"), ("internships/", "Internships"), ("hybrid/", "Hybrid jobs"), ("work-from-anywhere/", "Work-from-anywhere jobs")]
                  + [(p_, TYPE_NAMES.get(p_, h_)) for p_, h_, _, _ in HOURS] + ([("government-jobs/", "Government jobs")] if GOV_PAGE else []) + ([("nonprofit-jobs/", "Nonprofit jobs")] if NP_PAGE else []))
    FOOT["types"] = '<p class="pop"><span>Jobs by type:</span>' + "".join(f'<a href="{P}/{u_}">{e(n_)}</a>' for u_, n_ in TYPE_LINKS) + "</p>"
    # the open jobs of each list a "Related lists" row may name (kind_row), by the same filters and the same minimums as the lists below
    KIND_N.clear()
    KIND_N.update({p_: (TYPE_NAMES.get(p_, h_), len(js_)) for p_, h_, _, js_ in HOURS})
    et_n = Counter(j.get("etype") for j in active)
    KIND_N.update({p_: (l_, et_n[et_]) for et_, p_, l_ in (("Part-time", "part-time/", "Part-time jobs"), ("Contract", "contract/", "Contract jobs"), ("Internship", "internships/", "Internships")) if et_n[et_] >= 8})
    for p_, l_, k_, min_ in (("hybrid/", "Hybrid jobs", sum(1 for j in active if j.get("hybrid")), 20), ("work-from-anywhere/", "Work-from-anywhere jobs", sum(1 for j in remote if j.get("anywhere")), 8),
                             ("remote/", "Remote jobs", len(remote), 1), ("entry-level/", "Entry-level jobs", sum(1 for j in active if j["entry"]), 1),
                             ("government-jobs/", "Government jobs", len(gov_) if GOV_PAGE else 0, 1), ("nonprofit-jobs/", "Nonprofit jobs", len(np_) if NP_PAGE else 0, 1),
                             ("jobs-near-me/", "Jobs near me", len(active), 1), ("full-time-jobs-near-me/", "Full-time jobs near me", et_n["Full-time"], 20),
                             ("part-time-jobs-near-me/", "Part-time jobs near me", et_n["Part-time"], 20)):
        if k_ >= min_: KIND_N[p_] = (l_, k_)
    comp_items = sorted(companies.items(), key=lambda kv: -sum(j["active"] for j in kv[1]))
    SPONSORS = [sp for sp in CFG.get("sponsors", []) + PAID.get("sponsors", []) if sp.get("until", "") >= TODAY and sp.get("company") in companies]
    spot_cos = [sp["company"] for sp in SPONSORS if sp.get("slot") in ("home", "spotlight", "companies")]
    # company pages kept by the companies themselves in the account: a few lines about the company, its site and the places it hires in
    CLAIMED = {c_["company"]: c_ for c_ in PAID.get("claimed", []) if isinstance(c_, dict) and c_.get("company") in companies}
    def spot_tiles(names):
        return '<div class="spot">' + "".join(f'<a href="{P}/companies/{slugify(c)}/">{ava(c)}<span><b>{e(c)}</b><span class="s">{roles(OPEN[c], "open role")} · featured</span></span></a>' for c in names) + "</div>"
    def sponsor_line(slot):
        cs_ = [sp["company"] for sp in SPONSORS if sp.get("slot") == slot]
        # a paid place, and said so: the label, then the company with its logo and its open roles
        return ('<p class="sponsor"><span class="sponsor-l">Sponsored</span>' + "".join(
            f'<a href="{P}/companies/{slugify(c)}/">{ava(c)}<b>{e(c)}</b><span>{roles(OPEN[c], "open role")}</span></a>' for c in cs_) + "</p>") if cs_ else ""
    for s in CAT:
        SIM["cat"][s] = diverse(order(by_cat[s]), 12)
    by_comp_cat = defaultdict(list)
    for j in order(active):
        if len(by_comp_cat[(j["company"], j["cat"])]) < 4: by_comp_cat[(j["company"], j["cat"])].append(j)
    SIM["comp"] = by_comp_cat
    specific = [j for j in active if not j["pool"]]
    latest = diverse(order(specific), 40)

    lap('Home')
    # Home
    # The same as {s_: [j for j in active if role_hit(nm, rx, j["title"])] for nm, s_, rx in ROLES}, with each title tested once:
    # every role against every job was the largest single cost of a build (15 Nov 2026), and many titles repeat ("Store Associate").
    def jobs_by_role(js):
        of_title, out = role_slugs(j["title"] for j in js), {s_: [] for _, s_, _ in ROLES}
        for j in js:
            for s_ in of_title[j["title"]]: out[s_].append(j)
        return out
    ROLE_JOBS = jobs_by_role(active)
    by_role = {s_: (nm, ROLE_JOBS[s_]) for nm, s_, _ in ROLES if len(ROLE_JOBS[s_]) >= 20}
    fam_rows = []        # (slug, name, what kind of work, [(role slug, role name, jobs)], every job in the category once)
    for fs, fn, fd, rs in roles_info.FAMILIES:
        live = [(s_, by_role[s_][0], len(by_role[s_][1])) for s_ in rs if s_ in by_role]
        seen_, js_ = set(), []
        for s_, _, _ in live:
            for j in by_role[s_][1]:
                if j["id"] not in seen_: seen_.add(j["id"]); js_.append(j)
        if live: fam_rows.append((fs, fn, fd, live, js_))
    set_cat_home(fam_rows, by_role)
    fam_show = sorted(fam_rows, key=lambda f: -len(f[4]))      # by open jobs, so the order follows the jobs as sources grow (owner, 15 Nov: "IT first")
    # The footer's four biggest fields link the page that answers their search (25 Nov 2026: "Sales & Business Development" went to
    # /jobs/sales-bd/, whose canonical is /categories/sales/, on every page). one_page_per_query() decides that only once every page is
    # written, so the same test is made here, on the titles the two pages carry (listing() below); no page is written before this.
    fam_key = {query_key(f"{tcase(fn)} Jobs"): fs for fs, fn, _, _, _ in fam_rows}
    FOOT["cats"] = "".join(f'<li><a href="{P}/' + (f"categories/{fam_key[k_]}/" if (k_ := query_key(f"{CAT[s]} Jobs")) in fam_key else f"jobs/{s}/") + f'">{e(CAT[s])}</a></li>'
                           for s in top_cats[:4])
    TECH_FAMS = ["software-development", "ai-machine-learning", "data-analytics", "cloud-devops-it", "security", "product-project", "hardware-engineering"]
    lap("the hero's shortcut chips: among the roles people search for")
    # the hero's shortcut chips: among the roles people search for most, the three tech ones with the most open jobs, then two others
    # (the owner, 15 Nov: "IT first: people mostly look for IT"); the order follows the counts
    CHIP_TECH = ["software-engineer", "product-manager", "data-analyst", "data-scientist", "machine-learning-engineer", "devops-engineer", "cloud-engineer",
                 "cybersecurity", "frontend-engineer", "backend-engineer", "product-designer"]
    CHIP_OTHER = ["account-executive", "customer-support", "sales-representative", "marketing-manager", "project-manager", "recruiter", "accounting", "operations-manager"]
    by_n = lambda slugs: sorted((s_ for s_ in slugs if s_ in by_role), key=lambda s_: -len(by_role[s_][1]))
    hero_chips = "".join(f'<a href="{P}/roles/{s_}/">{e(by_role[s_][0][0].upper() + by_role[s_][0][1:])}</a>' for s_ in by_n(CHIP_TECH)[:3] + by_n(CHIP_OTHER)[:2])
    def dir_block(fs, fn, fd, live, js_, top=None, tag="h2"):
        return (f'<div class="dirb"><{tag}><a href="{P}/categories/{fs}/">{icon(fs)}<u>{e(fn)}</u></a><span>{len(js_):,}</span></{tag}><p>{e(fd[0].upper() + fd[1:])}.</p><ul>'
                + "".join(f'<li data-n="{e(nm.lower())}"><a href="{P}/roles/{s_}/">{e(nm)}</a><span>{c:,}</span></li>' for s_, nm, c in (live if top is None else live[:top]))
                + (f'<li class="more"><a href="{P}/categories/{fs}/">All {len(live)} in {e(rlow(fn))}</a></li>' if top is not None and len(live) > top else "") + "</ul></div>")
    ROLE_TOP = sorted(((nm, s_, len(ROLE_JOBS[s_])) for nm, s_, _ in ROLES if s_ in ROLE_BASE), key=lambda x: -x[2])
    lap('Pictures before words (the owner: "I cannot read walls of te')
    # Pictures before words (the owner: "I cannot read walls of text: more charts and infographics everywhere").
    # Every picture is counted from the open postings on this build; each has one caption that says what it shows.
    # Charts (the owner, 14 Nov: "dumb charts, not necessarily green on black, more modern"): light cards, one blue for magnitude and
    # orange only for the one mark a chart is about, thin columns with rounded ends, a few gridlines, selective labels and a tooltip
    # on every mark (hover or keyboard focus). Colours are tokens (--viz-1, --viz-2) with their own dark-mode steps in style.css.
    def nice_top(v):
        if v <= 0: return 1
        mag = 10 ** (len(str(int(v))) - 1)
        for k in (1, 1.2, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10):
            if v <= k * mag: return int(k * mag)
        return int(10 * mag)
    def vcols(points, hi=None, now=None, aria=""):
        """points: [(label under the column, value, tooltip)]. hi: index of the column the chart is about (orange, labelled);
        now: index of a period still filling up (lighter). The tallest column and hi carry their value; every column a tooltip."""
        top = nice_top(max((v for _, v, _ in points), default=0))
        peak = max(range(len(points)), key=lambda i: points[i][1]) if points else None
        grid = "".join(f'<span style="bottom:{100 * (top * t // 2) / top:.1f}%"><em>{fmt_n(top * t // 2)}</em></span>' for t in (1, 2))      # the line sits at its own figure ("7" of 15 is not halfway)
        bars = "".join(
            f'<div class="vc-c{" hi" if i == hi else ""}{" now" if i == now else ""}" role="img" tabindex="0" data-tip="{e(tip)}" aria-label="{e(tip)}">'
            f'<i style="height:{max(1.5, 100 * v / top):.1f}%">{f"<b>{fmt_n(v)}</b>" if i in (peak, hi) else ""}</i></div>'
            for i, (_, v, tip) in enumerate(points))
        xs = "".join(f'<span{" class=" + chr(34) + "hi" + chr(34) if i == hi else ""}>{e(lb)}</span>' for i, (lb, _, _) in enumerate(points))
        table = ('<table class="sr-only"><tr><th>Period</th><th>Count</th></tr>'
                 + "".join(f"<tr><td>{e(tip.split(' · ')[0])}</td><td>{v:,}</td></tr>" for _, v, tip in points) + "</table>")
        return (f'<div class="vc" role="group" aria-label="{e(aria)}"><div class="vc-plot"><div class="vc-grid">{grid}</div>'
                f'<div class="vc-cols">{bars}</div></div><div class="vc-x">{xs}</div>{table}</div>')
    def fmt_n(v):
        return f"{v / 1000:.1f}K".replace(".0K", "K") if v >= 10000 else f"{v:,}"
    def cols(pairs, hi_=None):                      # the older call: [(label, value)]
        return vcols([(lb, v, f"{lb} · {v:,} jobs") for lb, v in pairs], hi_)
    def meter(part, whole, label):
        """A stat tile: the share as a number, the count it comes from, and a thin bar of the share."""
        pc = round(100 * part / max(1, whole))
        return (f'<div class="st"><span class="st-l">{e(label[0].upper() + label[1:])}</span><b class="st-v">{pc}%</b>'
                f'<span class="st-m" role="img" aria-label="{pc}% {e(label)}"><i style="width:{max(1, pc)}%"></i></span>'
                f'<span class="st-s">{part:,} of {whole:,} jobs</span></div>')
    def donut(part, whole, label):                  # kept name: the three-number pictures are stat tiles now
        return meter(part, whole, label)
    def mini_pics(js):
        """Two pictures for a list of jobs: what they pay (when at least 30 state it) and three rings."""
        if len(js) < 20: return ""
        mids_ = [(j["usd"][0] + j["usd"][1]) / 2 for j in js if j["usd"]]
        pay = ""
        if len(mids_) >= 30:
            eg = [(0, 75), (75, 100), (100, 125), (125, 150), (150, 175), (175, 200), (200, 250), (250, 300), (300, 10 ** 6)]
            md_ = median(mids_)
            pay = (f'<figure class="pic"><figcaption><b>What these jobs pay</b>{len(mids_):,} of them state a yearly range in US dollars (bands in thousands). The marked column holds the median, {money(md_)}.</figcaption>'
                   + vcols([(("<75" if lo == 0 else f"{lo}+" if hi > 1000 else f"{lo}"), c_,
                              f"{'under $75K' if lo == 0 else f'${lo}K and more' if hi > 1000 else f'${lo}K to ${hi}K'} · {c_:,} postings")
                             for lo, hi in eg for c_ in [sum(1 for v in mids_ if lo * 1000 <= v < hi * 1000)]],
                            hi=next((i for i, (lo, hi) in enumerate(eg) if lo * 1000 <= md_ < hi * 1000), None), aria="Postings by yearly pay band") + "</figure>")
        rings = (f'<figure class="pic"><figcaption><b>Three numbers</b>Out of {len(js):,} open jobs in this list.</figcaption><div class="stats3">'
                 + donut(sum(j["remote"] for j in js), len(js), "can be done from home") + donut(sum(bool(j["salary"]) for j in js), len(js), "state the pay")
                 + donut(sum(1 for j in js if j["entry"]), len(js), "are for beginners") + "</div></figure>")
        return f'<div class="pics two">{pay}{rings}</div>'
    fam_top = sorted(fam_rows, key=lambda f: -len(f[4]))[:10]
    pic_fields = '<div class="hbars">' + "".join(
        f'<a href="{P}/categories/{fs}/"><span class="hn">{e(fn)}</span><span class="hb"><i style="width:{max(3, round(100 * len(js_) / len(fam_top[0][4])))}%"></i></span><span class="hc">{len(js_):,}</span></a>' for fs, fn, _, _, js_ in fam_top) + "</div>"
    mids_all = [(j["usd"][0] + j["usd"][1]) / 2 for j in active if j["usd"]]
    edges = [(0, 75), (75, 100), (100, 125), (125, 150), (150, 175), (175, 200), (200, 250), (250, 300), (300, 10 ** 6)]
    pay_lb = lambda lo, hi: "<75" if lo == 0 else f"{lo}+" if hi > 1000 else f"{lo}"          # thousands of dollars; the caption says so
    pay_tip = lambda lo, hi: "under $75K" if lo == 0 else f"${lo}K and more" if hi > 1000 else f"${lo}K to ${hi}K"
    med_all = median(mids_all) if mids_all else 0
    q_srt = sorted(mids_all)
    q_lo, q_hi = (q_srt[len(q_srt) // 4], q_srt[(3 * len(q_srt)) // 4]) if q_srt else (0, 0)
    med_i = next((i for i, (lo, hi) in enumerate(edges) if lo * 1000 <= med_all < hi * 1000), None)
    pay_pts = [(pay_lb(lo, hi), c_, f"{pay_tip(lo, hi)} · {c_:,} postings" + (" · the median is here" if i == med_i else ""))
               for i, (lo, hi) in enumerate(edges) for c_ in [sum(1 for v in mids_all if lo * 1000 <= v < hi * 1000)]]
    lap('New jobs: by day (the last 14 days and today so far) or by w')
    # New jobs: by day (the last 14 days and today so far) or by week (the last 12 weeks and this one so far). Counted from the
    # jobs still open, by the day the employer posted them; today and this week are drawn lighter because they are still filling.
    today_ = datetime.date.today()
    by_day = Counter((j["posted"] or "")[:10] for j in active)
    days15 = [today_ - datetime.timedelta(days=d) for d in range(14, -1, -1)]
    day_pts = [(f"{d.day}", by_day.get(d.isoformat(), 0), f"{'Today so far' if d == today_ else d.strftime('%a, %b ') + str(d.day)} · {by_day.get(d.isoformat(), 0):,} new jobs") for d in days15]
    wk0 = today_ - datetime.timedelta(days=today_.weekday())
    weeks = [wk0 - datetime.timedelta(weeks=w) for w in range(12, -1, -1)]
    def wk_count(w):
        return sum(by_day.get((w + datetime.timedelta(days=k)).isoformat(), 0) for k in range(7))
    wk_pts = [(f"{w.strftime('%b')} {w.day}" if i % 3 == 0 or w == wk0 else "", wk_count(w),
               f"{'This week so far' if w == wk0 else 'Week of ' + w.strftime('%b ') + str(w.day)} · {wk_count(w):,} new jobs") for i, w in enumerate(weeks)]
    n_pay, n_ent = sum(bool(j["salary"]) for j in active), sum(1 for j in active if j["entry"])
    new_jobs_fig = ('<figure class="pic"><figcaption><b>New jobs</b>Jobs still open, by the day the employer posted them. '
                    'The last column is still filling up.</figcaption>'
                    '<div class="vtabs"><input type="radio" name="nj" id="nj-d" checked><label for="nj-d">By day</label>'
                    '<input type="radio" name="nj" id="nj-w"><label for="nj-w">By week</label>'
                    f'<div class="vtab" id="nj-dp">{vcols(day_pts, now=len(day_pts) - 1, aria="New jobs by day, last 14 days and today")}</div>'
                    f'<div class="vtab" id="nj-wp">{vcols(wk_pts, now=len(wk_pts) - 1, aria="New jobs by week, last 12 weeks and this week")}</div></div></figure>')
    market_pics = ('<div class="pics">'
                   f'<figure class="pic"><figcaption><b>Where the jobs are</b>Open jobs in the ten largest fields. A job can count in two fields.</figcaption>{pic_fields}</figure>'
                   f'<figure class="pic"><figcaption><b>What the postings pay</b>{len(mids_all):,} postings state a yearly range in US dollars: '
                   f'how many sit in each band, by the middle of their range, in thousands of dollars. The marked column holds the median, {money(med_all)}.</figcaption>'
                   f'{vcols(pay_pts, hi=med_i, aria="Postings by yearly pay band")}'
                   + (f'<p class="vc-note"><span><b>{money(med_all)}</b>median</span><span><b>{money(q_lo)}–{money(q_hi)}</b>the middle half of postings</span>'
                      f'<span><b>{sum(1 for v in mids_all if v >= 200000):,}</b>pay $200K or more</span></p>' if mids_all else "") + '</figure>'
                   f'<figure class="pic"><figcaption><b>Three numbers about today’s jobs</b>Out of {n:,} open jobs.</figcaption><div class="stats3">'
                   + meter(len(remote), n, "can be done from home") + meter(n_pay, n, "state the pay") + meter(n_ent, n, "are for beginners") + "</div></figure>"
                   + new_jobs_fig + "</div>")
    ROLE_TOP = [x for x in ROLE_TOP if x[2] >= 20][:12]
    # groupings that have a page among the roles but are not a job title a person holds (defined here, not further down, because the tools need it first)
    BROAD = {"analyst", "coordinator", "director", "executive", "growth", "intern", "staff-engineer", "founding-team", "bilingual", "government", "energy", "payments", "consulting", "operators"}
    # /tools/resume-skills/, "skills to put on a resume" by job title: for each job title with a page, the skills its open postings name most.
    # A skill needs 3 postings and 5% of the title's postings to count; a title needs 3 such skills, the first of them in 10% of its postings
    # (postings for most sales, legal and office work name too few tools to say anything, so those titles are left out rather than shown thin).
    # The ten titles with the most postings are a table on the page itself; tools.js reads all of them from data/role-skills.json.
    # The tool's page and tools_test.js state these thresholds: change all three together.
    ROLE_SKILLS = []            # (role slug, role name, postings, [(skill, postings that name it), …]), most postings first
    for s_, (nm_, js_) in sorted(by_role.items(), key=lambda kv: (-len(kv[1][1]), kv[0])):
        if s_ in BROAD or s_.endswith("-speaking"): continue
        cnt_ = Counter(t for j in js_ for t in j["tags"])
        top_ = [(t, k) for t, k in sorted(cnt_.items(), key=lambda kv: (-kv[1], kv[0].lower())) if k >= max(3, len(js_) * 0.05)][:15]
