    shot_panels = "".join(f'<ul class="jobs" data-panel="{i_}"{" data-live=home" if i_ == 0 else " hidden"}>{r_}</ul>' for i_, (_, _, r_) in enumerate(shot_tabs))   # "Latest jobs" takes new jobs live (site.js)
