    ent_rank = sorted(((sum(1 for j in v if j.get("entry")) / len(v), CAT[c_], sum(1 for j in v if j.get("entry"))) for c_, v in by_cat.items() if len(v) >= 100 and c_ != OTHER[0]), reverse=True)[:3]
