    city_n = Counter()
    for j in active:
        for part in re.split(r"[;|·]| / |\bor\b", j["location"] or ""):
            c_ = re.sub(r"\b(?:remote|hybrid|on-?site|office)\b.*$", "", re.sub(r"\(.*?\)", "", part.split(",")[0]), flags=re.I).strip()
