    trust = lambda items: '<ul class="ptrust">' + "".join(f"<li>{e(x)}</li>" for x in items) + "</ul>"
    fit = lambda rows_: '<div class="pfit">' + "".join(f"<div><b>{e(a)}</b>{e(b)}</div>" for a, b in rows_) + "</div>"
