             '.st-tiles span{display:block;font-size:13px;color:var(--muted,#667)}.st-tiles b{font-size:24px}.st-card{border:1px solid var(--line,#e3e5ee);border-radius:12px;padding:14px 16px;margin:0 0 14px}'
