    if top_sk: badges.append((f"{top_sk} jobs", f"badge/skills/{tslug(top_sk)}.svg", f"skills/{tslug(top_sk)}/", badge_w(f"{top_sk} jobs", f"{len(by_tag.get(top_sk, ())):,} open")))
